insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('de7d51ab-a9ff-5577-9430-4cc31272d494', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '94', '‏ ‏حَدَّثَنِي ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَرْغَبُوا عَنْ آبَائِكُمْ فَمَنْ رَغِبَ عَنْ أَبِيهِ فَهُوَ كُفْرٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3adb3222-05a5-52fc-99e1-72264daa3a52', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '95', '‏ ‏حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏قَالَ ‏ ‏لَمَّا ادُّعِيَ ‏ ‏زِيَادٌ ‏ ‏لَقِيتُ ‏ ‏أَبَا بَكْرَةَ ‏ ‏فَقُلْتُ لَهُ مَا هَذَا الَّذِي صَنَعْتُمْ إِنِّي ‏ ‏سَمِعْتُ ‏ ‏سَعْدَ بْنَ أَبِي وَقَّاصٍ ‏ ‏يَقُولُا ‏ ‏سَمِعَ أُذُنَايَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏مَنْ ادَّعَى أَبًا فِي الْإِسْلَامِ غَيْرَ أَبِيهِ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏ ‏فَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏وَأَنَا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('607eeb47-9d0e-5ed9-86dd-ec86869cc667', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '96', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّاءَ بْنِ أَبِي زَائِدَةَ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏وَأَبِي بَكْرَةَ ‏ ‏كِلَاهُمَا ‏ ‏يَقُولُا ‏ ‏سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ وَهُوَ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ فَالْجَنَّةُ عَلَيْهِ حَرَامٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fb04a6d6-82e8-509a-b1f0-aed23633ca57', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '97', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكَّارِ بْنِ الرَّيَّانِ ‏ ‏وَعَوْنُ بْنُ سَلَّامٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ طَلْحَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِبَابُ الْمُسْلِمِ فُسُوقٌ وَقِتَالُهُ كُفْرٌ ‏ ‏قَالَ ‏ ‏زُبَيْدٌ ‏ ‏فَقُلْتُ ‏ ‏لِأَبِي وَائِلٍ ‏ ‏أَنْتَ سَمِعْتَهُ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏يَرْوِيهِ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ وَلَيْسَ فِي حَدِيثِ ‏ ‏شُعْبَةَ ‏ ‏قَوْلُ ‏ ‏زُبَيْدٍ ‏ ‏لِأَبِي وَائِلٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَابْنُ الْمُثَنَّى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0cf57446-3848-551d-b0e9-70a1625c9797', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '98', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُدْرِكٍ ‏ ‏سَمِعَ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏جَدِّهِ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ اسْتَنْصِتْ النَّاسَ ثُمَّ قَالَ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3da295fc-5dda-5cd7-b1c9-cfa698d6f611', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '99', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو بَكْرِ بْنُ خَلَّادٍ الْبَاهِلِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاقِدِ بْنِ مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي حَجَّةِ الْوَدَاعِ وَيْحَكُمْ ‏ ‏أَوْ قَالَ وَيْلَكُمْ ‏ ‏لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏ ‏حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏وَاقِدٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('50fd3ac2-fa06-5efd-9f6e-f508f831a0a9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '100', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اثْنَتَانِ فِي النَّاسِ هُمَا بِهِمْ كُفْرٌ الطَّعْنُ فِي النَّسَبِ وَالنِّيَاحَةُ عَلَى الْمَيِّتِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a11a865b-558b-5a7d-af3a-4cd2b23e2e96', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '101', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ يَعْنِي ابْنَ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏مَنْصُورِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّهُ سَمِعَهُ يَقُولُ ‏ ‏أَيُّمَا عَبْدٍ أَبَقَ مِنْ مَوَالِيهِ فَقَدْ كَفَرَ حَتَّى يَرْجِعَ إِلَيْهِمْ ‏ ‏قَالَ ‏ ‏مَنْصُورٌ ‏ ‏قَدْ وَاللَّهِ رُوِيَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنِّي أَكْرَهُ أَنْ يُرْوَى عَنِّي هَهُنَا ‏ ‏بِالْبَصْرَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('82aa3e2d-ba0b-57fa-b056-c2ca37c919ae', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '102', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا عَبْدٍ أَبَقَ فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4aea328e-e445-5d49-b244-b0f6c2d21977', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '103', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ كَانَ ‏ ‏جَرِيرُ بْنُ عَبْدِ اللَّهِ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَبَقَ الْعَبْدُ لَمْ تُقْبَلْ لَهُ صَلَاةٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('338de9cd-2944-5c43-962d-9c4e11357bdd', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '104', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الصُّبْحِ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فِي إِثْرِ السَّمَاءِ كَانَتْ مِنْ اللَّيْلِ فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَى النَّاسِ فَقَالَ هَلْ تَدْرُونَ مَاذَا قَالَ رَبُّكُمْ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ قَالَ ‏ ‏أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ فَأَمَّا مَنْ قَالَ مُطِرْنَا بِفَضْلِ اللَّهِ وَرَحْمَتِهِ فَذَلِكَ مُؤْمِنٌ بِي كَافِرٌ بِالْكَوْكَبِ وَأَمَّا مَنْ قَالَ مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا فَذَلِكَ كَافِرٌ بِي مُؤْمِنٌ بِالْكَوْكَبِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7096b128-c631-5d4f-bf17-b3659d4b11c2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '105', '‏ ‏حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏وَعَمْرُو بْنُ سَوَّادٍ الْعَامِرِيُّ ‏ ‏وَمُحَمَّدُ بْنُ سَلَمَةَ الْمُرَادِيُّ ‏ ‏قَالَ ‏ ‏الْمُرَادِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ تَرَوْا إِلَى مَا قَالَ رَبُّكُمْ قَالَ ‏ ‏مَا أَنْعَمْتُ عَلَى عِبَادِي مِنْ نِعْمَةٍ إِلَّا أَصْبَحَ فَرِيقٌ مِنْهُمْ بِهَا كَافِرِينَ يَقُولُونَ الْكَوَاكِبُ وَبِالْكَوَاكِبِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('414e9680-bfe0-5ad5-b4f2-7e450878d8cc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '106', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ الْمُرَادِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏عَمْرُو بْنُ سَوَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أَبَا يُونُسَ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَنْزَلَ اللَّهُ مِنْ السَّمَاءِ مِنْ بَرَكَةٍ إِلَّا أَصْبَحَ فَرِيقٌ مِنْ النَّاسِ بِهَا كَافِرِينَ يُنْزِلُ اللَّهُ الْغَيْثَ فَيَقُولُونَ الْكَوْكَبُ كَذَا وَكَذَا ‏ ‏وَفِي حَدِيثِ ‏ ‏الْمُرَادِيِّ ‏ ‏بِكَوْكَبِ كَذَا وَكَذَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6fba3796-3b0e-5cf4-94fd-2e3ba5e65992', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '107', '‏ ‏و حَدَّثَنِي ‏ ‏عَبَّاسُ بْنُ عَبْدِ الْعَظِيمِ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ وَهُوَ ابْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو زُمَيْلٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏قَالَ مُطِرَ النَّاسُ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْبَحَ مِنْ النَّاسِ شَاكِرٌ وَمِنْهُمْ كَافِرٌ قَالُوا هَذِهِ رَحْمَةُ اللَّهِ وَقَالَ بَعْضُهُمْ لَقَدْ صَدَقَ نَوْءُ كَذَا وَكَذَا قَالَ فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏فَلَا أُقْسِمُ بِمَوَاقِعِ النُّجُومِ ‏ ‏حَتَّى بَلَغَ ‏ ‏وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ ‏}', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('976e5244-3406-5b5b-8a10-3442dbcd125a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '108', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آيَةُ الْمُنَافِقِ بُغْضُ ‏ ‏الْأَنْصَارِ ‏ ‏وَآيَةُ الْمُؤْمِنِ حُبُّ ‏ ‏الْأَنْصَارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('69f7409a-267d-5c31-997c-4a4f4ab94370', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '109', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏حُبُّ ‏ ‏الْأَنْصَارِ ‏ ‏آيَةُ الْإِيمَانِ وَبُغْضُهُمْ آيَةُ النِّفَاقِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3818936c-6cfd-5659-8728-2f3e781c16f6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '110', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْبَرَاءَ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ فِي ‏ ‏الْأَنْصَارِ ‏ ‏لَا يُحِبُّهُمْ إِلَّا مُؤْمِنٌ وَلَا يُبْغِضُهُمْ إِلَّا مُنَافِقٌ مَنْ أَحَبَّهُمْ أَحَبَّهُ اللَّهُ وَمَنْ أَبْغَضَهُمْ أَبْغَضَهُ اللَّهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْتُ ‏ ‏لِعَدِيٍّ ‏ ‏سَمِعْتَهُ مِنْ ‏ ‏الْبَرَاءِ ‏ ‏قَالَ إِيَّايَ حَدَّثَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6c3741fd-9adb-5763-b99c-b7344b829b3b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '111', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ الْقَارِيَّ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُبْغِضُ ‏ ‏الْأَنْصَارَ ‏ ‏رَجُلٌ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2338d606-e363-5aba-aeb2-203123d1b1e2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '112', '‏ ‏و حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُبْغِضُ ‏ ‏الْأَنْصَارَ ‏ ‏رَجُلٌ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c3f1ef8c-0618-5614-89fb-256f663f0dfe', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '113', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏قَالَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏وَالَّذِي فَلَقَ الْحَبَّةَ وَبَرَأَ النَّسَمَةَ إِنَّهُ لَعَهْدُ النَّبِيِّ الْأُمِّيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيَّ ‏ ‏أَنْ لَا يُحِبَّنِي إِلَّا مُؤْمِنٌ وَلَا يُبْغِضَنِي إِلَّا مُنَافِقٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d11a2b97-f10b-5f9c-a74e-557830157593', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '114', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحِ بْنِ الْمُهَاجِرِ الْمِصْرِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا ‏ ‏مَعْشَرَ ‏ ‏النِّسَاءِ تَصَدَّقْنَ وَأَكْثِرْنَ ‏ ‏الِاسْتِغْفَارَ فَإِنِّي رَأَيْتُكُنَّ أَكْثَرَ أَهْلِ النَّارِ فَقَالَتْ امْرَأَةٌ مِنْهُنَّ ‏ ‏جَزْلَةٌ ‏ ‏وَمَا لَنَا يَا رَسُولَ اللَّهِ أَكْثَرَ أَهْلِ النَّارِ قَالَ تُكْثِرْنَ اللَّعْنَ ‏ ‏وَتَكْفُرْنَ ‏ ‏الْعَشِيرَ ‏ ‏وَمَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَغْلَبَ لِذِي ‏ ‏لُبٍّ ‏ ‏مِنْكُنَّ قَالَتْ يَا رَسُولَ اللَّهِ وَمَا نُقْصَانُ الْعَقْلِ وَالدِّينِ قَالَ أَمَّا نُقْصَانُ الْعَقْلِ فَشَهَادَةُ امْرَأَتَيْنِ تَعْدِلُ شَهَادَةَ رَجُلٍ فَهَذَا نُقْصَانُ الْعَقْلِ وَتَمْكُثُ اللَّيَالِي مَا تُصَلِّي وَتُفْطِرُ فِي رَمَضَانَ فَهَذَا نُقْصَانُ الدِّينِ ‏ ‏و حَدَّثَنِيهِ ‏ ‏أَبُو الطَّاهِرِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ مُضَرَ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏ ‏و حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏وَأَبُو بَكْرِ بْنُ إِسْحَقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي مَرْيَمَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ وَهُوَ ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ مَعْنَى حَدِيثِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a65c163f-4012-558e-a042-b29056a6ab7b', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '115', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَرَأَ ابْنُ ‏ ‏آدَمَ ‏ ‏السَّجْدَةَ فَسَجَدَ اعْتَزَلَ الشَّيْطَانُ يَبْكِي يَقُولُ يَا وَيْلَهُ ‏ ‏وَفِي رِوَايَةِ ‏ ‏أَبِي كُرَيْبٍ ‏ ‏يَا وَيْلِي ‏ ‏أُمِرَ ابْنُ ‏ ‏آدَمَ ‏ ‏بِالسُّجُودِ فَسَجَدَ فَلَهُ الْجَنَّةُ وَأُمِرْتُ بِالسُّجُودِ فَأَبَيْتُ فَلِي النَّارُ ‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏بِهَذَا الْإِسْنَادِ مِثْلَهُ غَيْرَ أَنَّهُ قَالَ فَعَصَيْتُ فَلِي النَّارُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bbd4bdc3-47fc-5539-9c3e-fa9967f037cc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '116', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى التَّمِيمِيُّ ‏ ‏وَعُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَابِرًا ‏ ‏يَقُولُا ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكَ الصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2cd30777-0bda-5b19-bdd9-d928b729338e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '117', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُا ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْكِ وَالْكُفْرِ تَرْكُ الصَّلَاةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('024b0510-f5aa-5d90-be4a-21b0c86ded61', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '118', '‏ ‏و حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ أَبِي مُزَاحِمٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏ح ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ جَعْفَرِ بْنِ زِيَادٍ ‏ ‏أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ إِيمَانٌ بِاللَّهِ قَالَ ثُمَّ مَاذَا قَالَ الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ ثُمَّ مَاذَا قَالَ حَجٌّ مَبْرُورٌ ‏ ‏وَفِي رِوَايَةِ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏قَالَ إِيمَانٌ بِاللَّهِ وَرَسُولِهِ ‏ ‏و حَدَّثَنِيهِ ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e5e8f73-480e-51cf-adff-a3e347c5cca3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '119', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الرَّبِيعِ الزَّهْرَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏خَلَفُ بْنُ هِشَامٍ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مُرَاوِحٍ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الْأَعْمَالِ أَفْضَلُ قَالَ الْإِيمَانُ بِاللَّهِ وَالْجِهَادُ فِي سَبِيلِهِ قَالَ قُلْتُ أَيُّ الرِّقَابِ أَفْضَلُ قَالَ أَنْفَسُهَا عِنْدَ أَهْلِهَا وَأَكْثَرُهَا ثَمَنًا قَالَ قُلْتُ فَإِنْ لَمْ أَفْعَلْ قَالَ تُعِينُ صَانِعًا أَوْ تَصْنَعُ لِأَخْرَقَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ ضَعُفْتُ عَنْ بَعْضِ الْعَمَلِ قَالَ تَكُفُّ شَرَّكَ عَنْ النَّاسِ فَإِنَّهَا صَدَقَةٌ مِنْكَ عَلَى نَفْسِكَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَ ‏ ‏عَبْدٌ ‏ ‏أَخْبَرَنَا وَقَالَ ‏ ‏ابْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏مَوْلَى ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِي مُرَاوِحٍ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ غَيْرَ أَنَّهُ قَالَ فَتُعِينُ الصَّانِعَ أَوْ تَصْنَعُ لِأَخْرَقَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1d90265f-38ec-527a-adf5-c1abe981d694', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '120', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ الْعَيْزَارِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِيَاسٍ أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْعَمَلِ أَفْضَلُ قَالَ الصَّلَاةُ لِوَقْتِهَا قَالَ قُلْتُ ثُمَّ أَيٌّ قَالَ ‏ ‏بِرُّ ‏ ‏الْوَالِدَيْنِ قَالَ قُلْتُ ثُمَّ أَيٌّ قَالَ الْجِهَادُ فِي سَبِيلِ اللَّهِ فَمَا تَرَكْتُ أَسْتَزِيدُهُ إِلَّا ‏ ‏إِرْعَاءً ‏ ‏عَلَيْهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('90cef832-b061-5aea-81ee-1f11c4322daf', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '121', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عُمَرَ الْمَكِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ الْفَزَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو يَعْفُورٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ الْعَيْزَارِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا نَبِيَّ اللَّهِ ‏ ‏أَيُّ الْأَعْمَالِ أَقْرَبُ إِلَى الْجَنَّةِ قَالَ الصَّلَاةُ عَلَى مَوَاقِيتِهَا قُلْتُ وَمَاذَا يَا نَبِيَّ اللَّهِ قَالَ بِرُّ الْوَالِدَيْنِ قُلْتُ وَمَاذَا يَا نَبِيَّ اللَّهِ قَالَ الْجِهَادُ فِي سَبِيلِ اللَّهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4c1b4e49-d3db-5096-b366-197f5186dc79', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '122', '‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ الْعَيْزَارِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَاحِبُ هَذِهِ الدَّارِ وَأَشَارَ إِلَى دَارِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَحَبُّ إِلَى اللَّهِ قَالَ الصَّلَاةُ عَلَى وَقْتِهَا قُلْتُ ثُمَّ أَيٌّ قَالَ ثُمَّ بِرُّ الْوَالِدَيْنِ قُلْتُ ثُمَّ أَيٌّ قَالَ ثُمَّ الْجِهَادُ فِي سَبِيلِ اللَّهِ قَالَ حَدَّثَنِي بِهِنَّ وَلَوْ اسْتَزَدْتُهُ لَزَادَنِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏بِهَذَا الْإِسْنَادِ مِثْلَهُ وَزَادَ وَأَشَارَ إِلَى دَارِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَمَا سَمَّاهُ لَنَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('803a139c-c398-5a39-bd40-c5515f369008', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '123', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْضَلُ الْأَعْمَالِ ‏ ‏أَوْ الْعَمَلِ ‏ ‏الصَّلَاةُ لِوَقْتِهَا وَبِرُّ الْوَالِدَيْنِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('66283032-1640-5e47-842b-934382348682', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '124', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏وَقَالَ ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الذَّنْبِ أَعْظَمُ عِنْدَ اللَّهِ قَالَ أَنْ تَجْعَلَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ قَالَ قُلْتُ لَهُ إِنَّ ذَلِكَ لَعَظِيمٌ قَالَ قُلْتُ ثُمَّ أَيٌّ قَالَ ثُمَّ أَنْ تَقْتُلَ وَلَدَكَ مَخَافَةَ أَنْ يَطْعَمَ مَعَكَ قَالَ قُلْتُ ثُمَّ أَيٌّ قَالَ ثُمَّ أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d7d071ca-b874-55a7-bb68-6e1ccc32e627', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '125', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ شُرَحْبِيلَ ‏ ‏قَالَ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏أَيُّ الذَّنْبِ أَكْبَرُ عِنْدَ اللَّهِ قَالَ أَنْ تَدْعُوَ لِلَّهِ نِدًّا وَهُوَ خَلَقَكَ قَالَ ثُمَّ أَيٌّ قَالَ أَنْ تَقْتُلَ وَلَدَكَ مَخَافَةَ أَنْ يَطْعَمَ مَعَكَ قَالَ ثُمَّ أَيٌّ قَالَ أَنْ تُزَانِيَ حَلِيلَةَ جَارِكَ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ تَصْدِيقَهَا ‏ { ‏وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا ‏}', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ea194211-0fe2-5d8a-969f-46810dc3f3e2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '126', '‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُحَمَّدِ بْنِ بُكَيْرِ بْنِ مُحَمَّدٍ النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ ثَلَاثًا الْإِشْرَاكُ بِاللَّهِ وَعُقُوقُ الْوَالِدَيْنِ وَشَهَادَةُ الزُّورِ ‏ ‏أَوْ قَوْلُ الزُّورِ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَّكِئًا فَجَلَسَ فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا لَيْتَهُ سَكَتَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5e0b4896-d6e3-5010-88bc-dc7cfab17dec', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '127', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ وَهُوَ ابْنُ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْكَبَائِرِ قَالَ ‏ ‏الشِّرْكُ بِاللَّهِ وَعُقُوقُ الْوَالِدَيْنِ وَقَتْلُ النَّفْسِ وَقَوْلُ الزُّورِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0b45c396-7195-5712-b2fa-de46b6498e73', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '128', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْوَلِيدِ بْنِ عَبْدِ الْحَمِيدِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي بَكْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَبَائِرَ أَوْ سُئِلَ عَنْ الْكَبَائِرِ فَقَالَ ‏ ‏الشِّرْكُ بِاللَّهِ وَقَتْلُ النَّفْسِ ‏ ‏وَعُقُوقُ ‏ ‏الْوَالِدَيْنِ وَقَالَ أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ قَالَ قَوْلُ ‏ ‏الزُّورِ ‏ ‏أَوْ قَالَ شَهَادَةُ ‏ ‏الزُّورِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَكْبَرُ ظَنِّي أَنَّهُ شَهَادَةُ ‏ ‏الزُّورِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f828de5c-f2c5-54bc-a06e-67285412a549', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '129', '‏ ‏حَدَّثَنِي ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اجْتَنِبُوا السَّبْعَ ‏ ‏الْمُوبِقَاتِ ‏ ‏قِيلَ يَا رَسُولَ اللَّهِ وَمَا هُنَّ قَالَ الشِّرْكُ بِاللَّهِ وَالسِّحْرُ وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَأَكْلُ مَالِ الْيَتِيمِ وَأَكْلُ الرِّبَا ‏ ‏وَالتَّوَلِّي ‏ ‏يَوْمَ ‏ ‏الزَّحْفِ ‏ ‏وَقَذْفُ ‏ ‏الْمُحْصِنَاتِ ‏ ‏الْغَافِلَاتِ الْمُؤْمِنَاتِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('38704cf4-871f-56de-ac12-6d71c31badf8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '130', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ الْكَبَائِرِ شَتْمُ الرَّجُلِ وَالِدَيْهِ قَالُوا يَا رَسُولَ اللَّهِ وَهَلْ يَشْتِمُ الرَّجُلُ وَالِدَيْهِ قَالَ نَعَمْ يَسُبُّ أَبَا الرَّجُلِ فَيَسُبُّ أَبَاهُ وَيَسُبُّ أُمَّهُ فَيَسُبُّ أُمَّهُ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('76ab1e29-b45d-51d2-83f1-71579cdba27a', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '131', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَمُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏وَإِبْرَاهِيمُ بْنُ دِينَارٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ حَمَّادٍ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ تَغْلِبَ ‏ ‏عَنْ ‏ ‏فُضَيْلٍ الْفُقَيْمِيِّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ قَالَ ‏ ‏رَجُلٌ ‏ ‏إِنَّ الرَّجُلَ يُحِبُّ أَنْ يَكُونَ ثَوْبُهُ حَسَنًا وَنَعْلُهُ حَسَنَةً قَالَ إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ الْكِبْرُ ‏ ‏بَطَرُ ‏ ‏الْحَقِّ ‏ ‏وَغَمْطُ ‏ ‏النَّاسِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bdbab600-f749-5231-8fb4-7ef13913fe83', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '132', '‏ ‏حَدَّثَنَا ‏ ‏مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ ‏ ‏وَسُوَيْدُ بْنُ سَعِيدٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُسْهِرٍ ‏ ‏قَالَ ‏ ‏مِنْجَابٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَدْخُلُ النَّارَ أَحَدٌ فِي قَلْبِهِ مِثْقَالُ حَبَّةِ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ إِيمَانٍ وَلَا يَدْخُلُ الْجَنَّةَ أَحَدٌ فِي قَلْبِهِ مِثْقَالُ حَبَّةِ ‏ ‏خَرْدَلٍ ‏ ‏مِنْ كِبْرِيَاءَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('225a8fe1-24b7-5a31-a777-78fc6052eef4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '133', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ تَغْلِبَ ‏ ‏عَنْ ‏ ‏فُضَيْلٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ ‏ ‏كِبْرٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('12ce3c1c-9ef8-5793-be9e-fe4330a8748f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '134', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ وَقُلْتُ أَنَا وَمَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('47d1747e-2780-57d5-ade6-f00523c4f0bf', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '135', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَا الْمُوجِبَتَانِ فَقَالَ ‏ ‏مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ النَّارَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f6b317e1-1ff7-59c8-b579-3f0ce149e503', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '136', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو أَيُّوبَ الْغَيْلَانِيُّ سُلَيْمَانُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَحَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ لَقِيَ اللَّهَ لَا يُشْرِكُ بِهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ لَقِيَهُ يُشْرِكُ بِهِ دَخَلَ النَّارَ ‏ ‏قَالَ ‏ ‏أَبُو أَيُّوبَ ‏ ‏قَالَ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏و حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاذٌ وَهُوَ ابْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7850a872-15b3-5c91-bee0-611745a888f2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '137', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَ ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏وَاصِلٍ الْأَحْدَبِ ‏ ‏عَنْ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا ذَرٍّ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَبَشَّرَنِي أَنَّهُ مَنْ مَاتَ مِنْ أُمَّتِكَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا دَخَلَ الْجَنَّةَ قُلْتُ وَإِنْ زَنَى وَإِنْ سَرَقَ قَالَ وَإِنْ زَنَى وَإِنْ سَرَقَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('653b6c2c-2a9a-5f0c-8f8b-b2d64de8dbd2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '138', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَأَحْمَدُ بْنُ خِرَاشٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏أَنَّ ‏ ‏يَحْيَى بْنَ يَعْمَرَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا الْأَسْوَدِ الدِّيلِيَّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا ذَرٍّ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ نَائِمٌ عَلَيْهِ ثَوْبٌ أَبْيَضُ ثُمَّ أَتَيْتُهُ فَإِذَا هُوَ نَائِمٌ ثُمَّ أَتَيْتُهُ وَقَدْ اسْتَيْقَظَ فَجَلَسْتُ إِلَيْهِ فَقَالَ ‏ ‏مَا مِنْ عَبْدٍ قَالَ لَا إِلَهَ إِلَّا اللَّهُ ثُمَّ مَاتَ عَلَى ذَلِكَ إِلَّا دَخَلَ الْجَنَّةَ قُلْتُ وَإِنْ زَنَى وَإِنْ سَرَقَ قَالَ وَإِنْ زَنَى وَإِنْ سَرَقَ قُلْتُ وَإِنْ زَنَى وَإِنْ سَرَقَ قَالَ وَإِنْ زَنَى وَإِنْ سَرَقَ ثَلَاثًا ثُمَّ قَالَ فِي الرَّابِعَةِ عَلَى ‏ ‏رَغْمِ ‏ ‏أَنْفِ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ فَخَرَجَ ‏ ‏أَبُو ذَرٍّ ‏ ‏وَهُوَ يَقُولُ وَإِنْ ‏ ‏رَغِمَ ‏ ‏أَنْفُ ‏ ‏أَبِي ذَرٍّ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('aa0ed0c2-b47f-5dd5-a67d-7dcd9e30f24e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '139', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ ‏ ‏وَاللَّفْظُ مُتَقَارِبٌ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَدِيِّ بْنِ الْخِيَارِ ‏ ‏عَنْ ‏ ‏الْمِقْدَادِ بْنِ الْأَسْوَدِ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏أَنَّهُ قَالَ يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ لَقِيتُ رَجُلًا مِنْ الْكُفَّارِ فَقَاتَلَنِي فَضَرَبَ إِحْدَى يَدَيَّ بِالسَّيْفِ فَقَطَعَهَا ثُمَّ ‏ ‏لَاذَ ‏ ‏مِنِّي بِشَجَرَةٍ فَقَالَ أَسْلَمْتُ لِلَّهِ أَفَأَقْتُلُهُ يَا رَسُولَ اللَّهِ بَعْدَ أَنْ قَالَهَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقْتُلْهُ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُ قَدْ قَطَعَ يَدِي ثُمَّ قَالَ ذَلِكَ بَعْدَ أَنْ قَطَعَهَا أَفَأَقْتُلُهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقْتُلْهُ فَإِنْ قَتَلْتَهُ فَإِنَّهُ بِمَنْزِلَتِكَ قَبْلَ أَنْ تَقْتُلَهُ وَإِنَّكَ بِمَنْزِلَتِهِ قَبْلَ أَنْ يَقُولَ كَلِمَتَهُ الَّتِي قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏أَمَّا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏وَابْنُ جُرَيْجٍ ‏ ‏فَفِي حَدِيثِهِمَا قَالَ أَسْلَمْتُ لِلَّهِ كَمَا قَالَ ‏ ‏اللَّيْثُ ‏ ‏فِي حَدِيثِهِ ‏ ‏وَأَمَّا ‏ ‏مَعْمَرٌ ‏ ‏فَفِي حَدِيثِهِ فَلَمَّا أَهْوَيْتُ لِأَقْتُلَهُ قَالَ لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ يَزِيدَ اللَّيْثِيُّ ثُمَّ الْجُنْدَعِيُّ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ عَدِيِّ بْنِ الْخِيَارِ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏الْمِقْدَادَ بْنَ عَمْرِو بْنِ الْأَسْوَدِ الْكِنْدِيَّ ‏ ‏وَكَانَ حَلِيفًا ‏ ‏لِبَنِي زُهْرَةَ ‏ ‏وَكَانَ مِمَّنْ شَهِدَ ‏ ‏بَدْرًا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ أَرَأَيْتَ إِنْ لَقِيتُ رَجُلًا مِنْ الْكُفَّارِ ثُمَّ ذَكَرَ بِمِثْلِ حَدِيثِ ‏ ‏اللَّيْثِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9e944b18-cece-5937-91c7-b2a5176046cc', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '140', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاوِيَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي ظِبْيَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏ابْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَرِيَّةٍ فَصَبَّحْنَا ‏ ‏الْحُرَقَاتِ ‏ ‏مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏فَأَدْرَكْتُ ‏ ‏رَجُلًا ‏ ‏فَقَالَ لَا إِلَهَ إِلَّا اللَّهُ فَطَعَنْتُهُ فَوَقَعَ فِي نَفْسِي مِنْ ذَلِكَ فَذَكَرْتُهُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَالَ لَا إِلَهَ إِلَّا اللَّهُ وَقَتَلْتَهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا قَالَهَا خَوْفًا مِنْ السِّلَاحِ قَالَ أَفَلَا شَقَقْتَ عَنْ قَلْبِهِ حَتَّى تَعْلَمَ أَقَالَهَا أَمْ لَا فَمَا زَالَ يُكَرِّرُهَا عَلَيَّ حَتَّى تَمَنَّيْتُ أَنِّي أَسْلَمْتُ يَوْمَئِذٍ قَالَ فَقَالَ ‏ ‏سَعْدٌ ‏ ‏وَأَنَا وَاللَّهِ لَا أَقْتُلُ مُسْلِمًا حَتَّى يَقْتُلَهُ ذُو الْبُطَيْنِ ‏ ‏يَعْنِي ‏ ‏أُسَامَةَ ‏ ‏قَالَ قَالَ رَجُلٌ أَلَمْ يَقُلْ اللَّهُ ‏ { ‏وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ ‏} ‏فَقَالَ ‏ ‏سَعْدٌ ‏ ‏قَدْ قَاتَلْنَا حَتَّى لَا تَكُونَ فِتْنَةٌ وَأَنْتَ وَأَصْحَابُكَ تُرِيدُونَ أَنْ تُقَاتِلُوا حَتَّى تَكُونُ فِتْنَةٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('dfc8bf10-243e-583b-aa67-098e1f981281', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '141', '‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ الدَّوْرَقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُصَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو ظِبْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُسَامَةَ بْنَ زَيْدِ بْنِ حَارِثَةَ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْحُرَقَةِ ‏ ‏مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏فَصَبَّحْنَا الْقَوْمَ فَهَزَمْنَاهُمْ وَلَحِقْتُ أَنَا وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏رَجُلًا ‏ ‏مِنْهُمْ فَلَمَّا غَشِينَاهُ قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَكَفَّ عَنْهُ الْأَنْصَارِيَّ وَطَعَنْتُهُ بِرُمْحِي حَتَّى قَتَلْتُهُ قَالَ فَلَمَّا قَدِمْنَا بَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي يَا ‏ ‏أُسَامَةُ ‏ ‏أَقَتَلْتَهُ بَعْدَ مَا قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا كَانَ مُتَعَوِّذًا قَالَ فَقَالَ أَقَتَلْتَهُ بَعْدَ مَا قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ فَمَا زَالَ يُكَرِّرُهَا عَلَيَّ حَتَّى تَمَنَّيْتُ أَنِّي لَمْ أَكُنْ أَسْلَمْتُ قَبْلَ ذَلِكَ الْيَوْمِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9013059f-85f0-5cf8-9f88-004f29cd551f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '142', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَسَنِ بْنِ خِرَاشٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏خَالِدًا الْأَثْبَجَ ‏ ‏ابْنَ أَخِي ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏حَدَّثَ عَنْ ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏أَنَّهُ حَدَّثَ ‏ ‏أَنَّ ‏ ‏جُنْدَبَ بْنَ عَبْدِ اللَّهِ الْبَجَلِيَّ ‏ ‏بَعَثَ إِلَى ‏ ‏عَسْعَسِ بْنِ سَلَامَةَ ‏ ‏زَمَنَ فِتْنَةِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏فَقَالَ اجْمَعْ لِي نَفَرًا مِنْ إِخْوَانِكَ حَتَّى أُحَدِّثَهُمْ فَبَعَثَ رَسُولًا إِلَيْهِمْ فَلَمَّا اجْتَمَعُوا جَاءَ ‏ ‏جُنْدَبٌ ‏ ‏وَعَلَيْهِ بُرْنُسٌ أَصْفَرُ فَقَالَ تَحَدَّثُوا بِمَا كُنْتُمْ تَحَدَّثُونَ بِهِ حَتَّى دَارَ الْحَدِيثُ فَلَمَّا دَارَ الْحَدِيثُ إِلَيْهِ حَسَرَ الْبُرْنُسَ عَنْ رَأْسِهِ فَقَالَ إِنِّي أَتَيْتُكُمْ وَلَا أُرِيدُ أَنْ أُخْبِرَكُمْ عَنْ نَبِيِّكُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ بَعْثًا مِنْ الْمُسْلِمِينَ إِلَى قَوْمٍ مِنْ الْمُشْرِكِينَ وَإِنَّهُمْ الْتَقَوْا فَكَانَ رَجُلٌ مِنْ الْمُشْرِكِينَ إِذَا شَاءَ أَنْ يَقْصِدَ إِلَى رَجُلٍ مِنْ الْمُسْلِمِينَ قَصَدَ لَهُ فَقَتَلَهُ وَإِنَّ رَجُلًا مِنْ الْمُسْلِمِينَ قَصَدَ غَفْلَتَهُ قَالَ وَكُنَّا نُحَدَّثُ أَنَّهُ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَلَمَّا رَفَعَ عَلَيْهِ السَّيْفَ قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَقَتَلَهُ فَجَاءَ ‏ ‏الْبَشِيرُ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ فَأَخْبَرَهُ حَتَّى أَخْبَرَهُ خَبَرَ الرَّجُلِ كَيْفَ صَنَعَ فَدَعَاهُ فَسَأَلَهُ فَقَالَ ‏ ‏لِمَ قَتَلْتَهُ قَالَ يَا رَسُولَ اللَّهِ أَوْجَعَ فِي الْمُسْلِمِينَ وَقَتَلَ فُلَانًا وَفُلَانًا وَسَمَّى لَهُ نَفَرًا وَإِنِّي حَمَلْتُ عَلَيْهِ فَلَمَّا رَأَى السَّيْفَ قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَتَلْتَهُ قَالَ نَعَمْ قَالَ فَكَيْفَ تَصْنَعُ ‏ ‏بِلَا إِلَهَ إِلَّا اللَّهُ إِذَا جَاءَتْ يَوْمَ الْقِيَامَةِ قَالَ يَا رَسُولَ اللَّهِ اسْتَغْفِرْ لِي قَالَ وَكَيْفَ تَصْنَعُ ‏ ‏بِلَا إِلَهَ إِلَّا اللَّهُ إِذَا جَاءَتْ يَوْمَ الْقِيَامَةِ قَالَ فَجَعَلَ لَا يَزِيدُهُ عَلَى أَنْ يَقُولَ كَيْفَ تَصْنَعُ ‏ ‏بِلَا إِلَهَ إِلَّا اللَّهُ إِذَا جَاءَتْ يَوْمَ الْقِيَامَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('6cb704c9-ae5c-5914-915e-892cdb3820a3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '143', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَحْيَى وَهُوَ الْقَطَّانُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏قَالَ قَرَأْتُ عَلَى ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
