insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bafcb7d4-fd07-57b1-87c1-2a7802429e12', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '145', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَرَّادٍ الْأَشْعَرِيُّ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏بُرَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1ddf2017-0d29-5814-9a0d-310f8e083a9c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '146', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ الْقَارِيُّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ مُحَمَّدُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي حَازِمٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا وَمَنْ غَشَّنَا فَلَيْسَ مِنَّا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('34b3c7b6-a6ac-567e-aa61-2a767389f923', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '147', '‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ عَلَى ‏ ‏صُبْرَةِ ‏ ‏طَعَامٍ فَأَدْخَلَ يَدَهُ فِيهَا ‏ ‏فَنَالَتْ ‏ ‏أَصَابِعُهُ بَلَلًا فَقَالَ مَا هَذَا يَا صَاحِبَ الطَّعَامِ قَالَ أَصَابَتْهُ السَّمَاءُ يَا رَسُولَ اللَّهِ قَالَ أَفَلَا جَعَلْتَهُ فَوْقَ الطَّعَامِ كَيْ يَرَاهُ النَّاسُ ‏ ‏مَنْ غَشَّ فَلَيْسَ مِنِّي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('11fff71d-0c02-5080-9b23-13086e5a50ec', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '148', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ مِنَّا مَنْ ضَرَبَ الْخُدُودَ أَوْ ‏ ‏شَقَّ الْجُيُوبَ ‏ ‏أَوْ دَعَا ‏ ‏بِدَعْوَى ‏ ‏الْجَاهِلِيَّةِ ‏ ‏هَذَا حَدِيثُ ‏ ‏يَحْيَى ‏ ‏وَأَمَّا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏فَقَالَا ‏ ‏وَشَقَّ وَدَعَا بِغَيْرِ أَلِفٍ ‏ ‏و حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَلِيُّ بْنُ خَشْرَمٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ وَقَالَا وَشَقَّ وَدَعَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('66ef99b3-eace-5d0e-9cd3-1ae8684a05f0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '149', '‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى الْقَنْطَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏أَنَّ ‏ ‏الْقَاسِمَ بْنَ مُخَيْمِرَةَ ‏ ‏حَدَّثَهُ قَالَ حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ بْنُ أَبِي مُوسَى ‏ ‏قَالَ ‏ ‏وَجِعَ ‏ ‏أَبُو مُوسَى ‏ ‏وَجَعًا ‏ ‏فَغُشِيَ عَلَيْهِ وَرَأْسُهُ فِي حَجْرِ امْرَأَةٍ مِنْ أَهْلِهِ فَصَاحَتْ امْرَأَةٌ مِنْ أَهْلِهِ فَلَمْ يَسْتَطِعْ أَنْ يَرُدَّ عَلَيْهَا شَيْئًا فَلَمَّا أَفَاقَ قَالَ أَنَا بَرِيءٌ مِمَّا بَرِئَ مِنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَرِئَ مِنْ ‏ ‏الصَّالِقَةِ ‏ ‏وَالْحَالِقَةِ ‏ ‏وَالشَّاقَّةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('43f14dfd-1db9-5885-a81f-e5bf72248f49', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '150', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏وَإِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏جَعْفَرُ بْنُ عَوْنٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عُمَيْسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا صَخْرَةَ ‏ ‏يَذْكُرُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏وَأَبِي بُرْدَةَ بْنِ أَبِي مُوسَى ‏ ‏قَالَا ‏ ‏أُغْمِيَ عَلَى ‏ ‏أَبِي مُوسَى ‏ ‏وَأَقْبَلَتْ امْرَأَتُهُ ‏ ‏أُمُّ عَبْدِ اللَّهِ ‏ ‏تَصِيحُ ‏ ‏بِرَنَّةٍ ‏ ‏قَالَا ثُمَّ أَفَاقَ قَالَ أَلَمْ تَعْلَمِي وَكَانَ يُحَدِّثُهَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَا بَرِيءٌ مِمَّنْ حَلَقَ ‏ ‏وَسَلَقَ ‏ ‏وَخَرَقَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُطِيعٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏عَنْ ‏ ‏عِيَاضٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏امْرَأَةِ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنِيهِ ‏ ‏حَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ يَعْنِي ابْنَ أَبِي هِنْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ مُحْرِزٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏أَبِي مُوسَى ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏غَيْرَ أَنَّ فِي حَدِيثِ ‏ ‏عِيَاضٍ الْأَشْعَرِيِّ ‏ ‏قَالَ لَيْسَ مِنَّا وَلَمْ يَقُلْ بَرِيءٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('31b2ed04-cdc1-54de-96cb-8f84aabbc980', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '151', '‏ ‏و حَدَّثَنِي ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَسْمَاءَ الضُّبَعِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَهْدِيٌّ وَهُوَ ابْنُ مَيْمُونٍ ‏ ‏حَدَّثَنَا ‏ ‏وَاصِلٌ الْأَحْدَبُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّهُ بَلَغَهُ أَنَّ رَجُلًا يَنُمُّ الْحَدِيثَ فَقَالَ ‏ ‏حُذَيْفَةُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏نَمَّامٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3e25023e-d18e-5571-aed2-29a18f94f0f8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '152', '‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حُجْرٍ السَّعْدِيُّ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ يَنْقُلُ الْحَدِيثَ إِلَى الْأَمِيرِ فَكُنَّا جُلُوسًا فِي الْمَسْجِدِ فَقَالَ الْقَوْمُ هَذَا مِمَّنْ يَنْقُلُ الْحَدِيثَ إِلَى الْأَمِيرِ قَالَ فَجَاءَ حَتَّى جَلَسَ إِلَيْنَا فَقَالَ ‏ ‏حُذَيْفَةُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏قَتَّاتٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff77a475-4383-54df-8276-00a2b19589a5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '153', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا مَعَ ‏ ‏حُذَيْفَةَ ‏ ‏فِي الْمَسْجِدِ فَجَاءَ رَجُلٌ حَتَّى جَلَسَ إِلَيْنَا فَقِيلَ ‏ ‏لِحُذَيْفَةَ ‏ ‏إِنَّ هَذَا يَرْفَعُ إِلَى السُّلْطَانِ أَشْيَاءَ فَقَالَ ‏ ‏حُذَيْفَةُ ‏ ‏إِرَادَةَ أَنْ يُسْمِعَهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَدْخُلُ الْجَنَّةَ ‏ ‏قَتَّاتٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('57775c7d-8a0d-53ff-a971-15b7b5c2a493', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '154', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ مُدْرِكٍ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏خَرَشَةَ بْنِ الْحُرِّ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ لَا يُكَلِّمُهُمْ اللَّهُ يَوْمَ الْقِيَامَةِ وَلَا يَنْظُرُ إِلَيْهِمْ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ قَالَ فَقَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَ مِرَارًا قَالَ ‏ ‏أَبُو ذَرٍّ ‏ ‏خَابُوا وَخَسِرُوا مَنْ هُمْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏الْمُسْبِلُ ‏ ‏وَالْمَنَّانُ ‏ ‏وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ الْكَاذِبِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('4cf0b5fd-1132-5995-afd5-eeda93f2e4b9', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '155', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ خَلَّادٍ الْبَاهِلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى وَهُوَ الْقَطَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏خَرَشَةَ بْنِ الْحُرِّ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ لَا يُكَلِّمُهُمْ اللَّهُ يَوْمَ الْقِيَامَةِ ‏ ‏الْمَنَّانُ ‏ ‏الَّذِي لَا يُعْطِي شَيْئًا إِلَّا مَنَّهُ وَالْمُنَفِّقُ سِلْعَتَهُ بِالْحَلِفِ الْفَاجِرِ ‏ ‏وَالْمُسْبِلُ ‏ ‏إِزَارَهُ ‏ ‏و حَدَّثَنِيهِ ‏ ‏بِشْرُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ ‏ ‏بِهَذَا الْإِسْنَادِ وَقَالَ ‏ ‏ثَلَاثَةٌ لَا يُكَلِّمُهُمْ اللَّهُ وَلَا يَنْظُرُ إِلَيْهِمْ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a94e4aee-f7b9-5407-9f2b-7a162322fcf0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '156', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثَةٌ لَا يُكَلِّمُهُمْ اللَّهُ يَوْمَ الْقِيَامَةِ وَلَا يُزَكِّيهِمْ ‏ ‏قَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَلَا يَنْظُرُ إِلَيْهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ ‏ ‏شَيْخٌ زَانٍ وَمَلِكٌ كَذَّابٌ ‏ ‏وَعَائِلٌ ‏ ‏مُسْتَكْبِرٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa8f6a12-2f1e-51dd-8991-432e94ddf852', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '157', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ لَا يُكَلِّمُهُمْ اللَّهُ يَوْمَ الْقِيَامَةِ وَلَا يَنْظُرُ إِلَيْهِمْ وَلَا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ رَجُلٌ عَلَى فَضْلِ مَاءٍ ‏ ‏بِالْفَلَاةِ ‏ ‏يَمْنَعُهُ مِنْ ابْنِ السَّبِيلِ وَرَجُلٌ بَايَعَ رَجُلًا بِسِلْعَةٍ بَعْدَ الْعَصْرِ فَحَلَفَ لَهُ بِاللَّهِ لَأَخَذَهَا بِكَذَا وَكَذَا فَصَدَّقَهُ وَهُوَ عَلَى غَيْرِ ذَلِكَ وَرَجُلٌ بَايَعَ إِمَامًا لَا يُبَايِعُهُ إِلَّا لِدُنْيَا فَإِنْ أَعْطَاهُ مِنْهَا وَفَى وَإِنْ لَمْ يُعْطِهِ مِنْهَا لَمْ يَفِ ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَمْرٍو الْأَشْعَثِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْثَرٌ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ مِثْلَهُ ‏ ‏غَيْرَ أَنَّ فِي حَدِيثِ ‏ ‏جَرِيرٍ ‏ ‏وَرَجُلٌ ‏ ‏سَاوَمَ ‏ ‏رَجُلًا بِسِلْعَةٍ ‏ ‏و حَدَّثَنِي ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ أُرَاهُ مَرْفُوعًا ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ لَا يُكَلِّمُهُمْ اللَّهُ وَلَا يَنْظُرُ إِلَيْهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ رَجُلٌ حَلَفَ عَلَى يَمِينٍ بَعْدَ صَلَاةِ الْعَصْرِ عَلَى مَالِ مُسْلِمٍ فَاقْتَطَعَهُ وَبَاقِي حَدِيثِهِ نَحْوُ حَدِيثِ ‏ ‏الْأَعْمَشِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('eff7fc3c-7bd6-5fbd-bb6a-e1f0f3bb6d2d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '158', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو سَعِيدٍ الْأَشَجُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ نَفْسَهُ بِحَدِيدَةٍ فَحَدِيدَتُهُ فِي يَدِهِ ‏ ‏يَتَوَجَّأُ ‏ ‏بِهَا فِي بَطْنِهِ فِي نَارِ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا وَمَنْ شَرِبَ سَمًّا فَقَتَلَ نَفْسَهُ فَهُوَ ‏ ‏يَتَحَسَّاهُ ‏ ‏فِي نَارِ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا وَمَنْ ‏ ‏تَرَدَّى ‏ ‏مِنْ جَبَلٍ فَقَتَلَ نَفْسَهُ فَهُوَ ‏ ‏يَتَرَدَّى ‏ ‏فِي نَارِ جَهَنَّمَ خَالِدًا مُخَلَّدًا فِيهَا أَبَدًا ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَمْرٍو الْأَشْعَثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْثَرٌ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏يَحْيَى بْنُ حَبِيبٍ الْحَارِثِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ الْحَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏كُلُّهُمْ بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏ ‏وَفِي رِوَايَةِ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ذَكْوَانَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('7bb94181-25fd-53be-b1fe-21a4d844d193', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '159', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏مُعَاوِيَةُ بْنُ سَلَّامِ بْنِ أَبِي سَلَّامٍ الدِّمَشْقِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏أَنَّ ‏ ‏أَبَا قِلَابَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ثَابِتَ بْنَ الضَّحَّاكِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ بَايَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَحْتَ الشَّجَرَةِ وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ بِمِلَّةٍ غَيْرِ الْإِسْلَامِ كَاذِبًا فَهُوَ كَمَا قَالَ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ وَلَيْسَ عَلَى رَجُلٍ نَذْرٌ فِي شَيْءٍ لَا يَمْلِكُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('3d1ddceb-f701-5c24-b660-5b816da9c3e1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '160', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ وَهُوَ ابْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ عَلَى رَجُلٍ نَذْرٌ فِيمَا لَا يَمْلِكُ وَلَعْنُ الْمُؤْمِنِ كَقَتْلِهِ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ فِي الدُّنْيَا عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ وَمَنْ ادَّعَى دَعْوَى كَاذِبَةً لِيَتَكَثَّرَ بِهَا لَمْ يَزِدْهُ اللَّهُ إِلَّا قِلَّةً وَمَنْ حَلَفَ عَلَى ‏ ‏يَمِينِ صَبْرٍ ‏ ‏فَاجِرَةٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8e7e8476-94b8-589d-8195-8cfff2de8ed3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '161', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَإِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏وَعَبْدُ الْوَارِثِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏عَبْدِ الصَّمَدِ بْنِ عَبْدِ الْوَارِثِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ الْأَنْصَارِيِّ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏الثَّوْرِيِّ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ بِمِلَّةٍ سِوَى الْإِسْلَامِ كَاذِبًا مُتَعَمِّدًا فَهْوَ كَمَا قَالَ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عَذَّبَهُ اللَّهُ بِهِ فِي نَارِ جَهَنَّمَ ‏ ‏هَذَا حَدِيثُ ‏ ‏سُفْيَانَ ‏ ‏وَأَمَّا ‏ ‏شُعْبَةُ ‏ ‏فَحَدِيثُهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ بِمِلَّةٍ سِوَى الْإِسْلَامِ كَاذِبًا فَهْوَ كَمَا قَالَ وَمَنْ ذَبَحَ نَفْسَهُ بِشَيْءٍ ذُبِحَ بِهِ يَوْمَ الْقِيَامَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b85dac73-1a51-51f1-a12e-d523877437eb', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '162', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏ابْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏شَهِدْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُنَيْنًا ‏ ‏فَقَالَ ‏ ‏لِرَجُلٍ ‏ ‏مِمَّنْ يُدْعَى بِالْإِسْلَامِ ‏ ‏هَذَا مِنْ أَهْلِ النَّارِ فَلَمَّا حَضَرْنَا الْقِتَالَ قَاتَلَ ‏ ‏الرَّجُلُ ‏ ‏قِتَالًا شَدِيدًا فَأَصَابَتْهُ جِرَاحَةٌ فَقِيلَ يَا رَسُولَ اللَّهِ ‏ ‏الرَّجُلُ ‏ ‏الَّذِي قُلْتَ لَهُ آنِفًا إِنَّهُ مِنْ أَهْلِ النَّارِ فَإِنَّهُ قَاتَلَ الْيَوْمَ قِتَالًا شَدِيدًا وَقَدْ مَاتَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى النَّارِ فَكَادَ بَعْضُ الْمُسْلِمِينَ أَنْ ‏ ‏يَرْتَابَ ‏ ‏فَبَيْنَمَا هُمْ عَلَى ذَلِكَ إِذْ قِيلَ إِنَّهُ لَمْ يَمُتْ وَلَكِنَّ بِهِ جِرَاحًا شَدِيدًا فَلَمَّا كَانَ مِنْ اللَّيْلِ لَمْ يَصْبِرْ عَلَى الْجِرَاحِ فَقَتَلَ نَفْسَهُ فَأُخْبِرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ فَقَالَ اللَّهُ أَكْبَرُ أَشْهَدُ أَنِّي عَبْدُ اللَّهِ وَرَسُولُهُ ثُمَّ أَمَرَ ‏ ‏بِلَالًا ‏ ‏فَنَادَى فِي النَّاسِ أَنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا نَفْسٌ مُسْلِمَةٌ وَأَنَّ اللَّهَ يُؤَيِّدُ هَذَا الدِّينَ بِالرَّجُلِ الْفَاجِرِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('92f51961-2bfd-5252-80df-62e9c40b949c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '163', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ الْقَارِيُّ ‏ ‏حَيٌّ مِنْ ‏ ‏الْعَرَبِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْتَقَى هُوَ وَالْمُشْرِكُونَ فَاقْتَتَلُوا فَلَمَّا مَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى عَسْكَرِهِ وَمَالَ الْآخَرُونَ إِلَى عَسْكَرِهِمْ وَفِي ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ ‏ ‏لَا يَدَعُ لَهُمْ ‏ ‏شَاذَّةً ‏ ‏إِلَّا اتَّبَعَهَا يَضْرِبُهَا بِسَيْفِهِ فَقَالُوا مَا أَجْزَأَ مِنَّا الْيَوْمَ أَحَدٌ كَمَا أَجْزَأَ ‏ ‏فُلَانٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَا إِنَّهُ مِنْ أَهْلِ النَّارِ فَقَالَ ‏ ‏رَجُلٌ ‏ ‏مِنْ الْقَوْمِ أَنَا صَاحِبُهُ أَبَدًا قَالَ فَخَرَجَ مَعَهُ كُلَّمَا وَقَفَ وَقَفَ مَعَهُ وَإِذَا أَسْرَعَ أَسْرَعَ مَعَهُ قَالَ فَجُرِحَ ‏ ‏الرَّجُلُ ‏ ‏جُرْحًا شَدِيدًا فَاسْتَعْجَلَ الْمَوْتَ فَوَضَعَ نَصْلَ سَيْفِهِ بِالْأَرْضِ ‏ ‏وَذُبَابَهُ ‏ ‏بَيْنَ ثَدْيَيْهِ ثُمَّ تَحَامَلَ عَلَى سَيْفِهِ فَقَتَلَ نَفْسَهُ فَخَرَجَ ‏ ‏الرَّجُلُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَشْهَدُ أَنَّكَ رَسُولُ اللَّهِ قَالَ وَمَا ذَاكَ قَالَ ‏ ‏الرَّجُلُ ‏ ‏الَّذِي ذَكَرْتَ آنِفًا أَنَّهُ مِنْ أَهْلِ النَّارِ فَأَعْظَمَ النَّاسُ ذَلِكَ فَقُلْتُ أَنَا لَكُمْ بِهِ فَخَرَجْتُ فِي طَلَبِهِ حَتَّى جُرِحَ جُرْحًا شَدِيدًا فَاسْتَعْجَلَ الْمَوْتَ فَوَضَعَ ‏ ‏نَصْلَ ‏ ‏سَيْفِهِ بِالْأَرْضِ ‏ ‏وَذُبَابَهُ ‏ ‏بَيْنَ ثَدْيَيْهِ ثُمَّ تَحَامَلَ عَلَيْهِ فَقَتَلَ نَفْسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ ‏ ‏إِنَّ الرَّجُلَ لِيَعْمَلُ عَمَلَ أَهْلِ الْجَنَّةِ فِيمَا يَبْدُو لِلنَّاسِ وَهُوَ مِنْ أَهْلِ النَّارِ وَإِنَّ الرَّجُلَ لِيَعْمَلُ عَمَلَ أَهْلِ النَّارِ فِيمَا يَبْدُو لِلنَّاسِ وَهُوَ مِنْ أَهْلِ الْجَنَّةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('91b69890-1f96-59cd-bb50-5d692fb311c1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '164', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏الزُّبَيْرِيُّ وَهُوَ مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُا ‏ ‏إِنَّ رَجُلًا مِمَّنْ كَانَ قَبْلَكُمْ خَرَجَتْ بِهِ ‏ ‏قُرْحَةٌ ‏ ‏فَلَمَّا آذَتْهُ انْتَزَعَ سَهْمًا مِنْ ‏ ‏كِنَانَتِهِ ‏ ‏فَنَكَأَهَا ‏ ‏فَلَمْ ‏ ‏يَرْقَأْ ‏ ‏الدَّمُ حَتَّى مَاتَ قَالَ رَبُّكُمْ قَدْ حَرَّمْتُ عَلَيْهِ الْجَنَّةَ ثُمَّ مَدَّ يَدَهُ إِلَى الْمَسْجِدِ فَقَالَ إِي وَاللَّهِ لَقَدْ حَدَّثَنِي بِهَذَا الْحَدِيثِ ‏ ‏جُنْدَبٌ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَسْجِدِ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي بَكْرٍ الْمُقَدَّمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ حَدَّثَنَا ‏ ‏جُنْدَبُ بْنُ عَبْدِ اللَّهِ الْبَجَلِيُّ ‏ ‏فِي هَذَا الْمَسْجِدِ فَمَا نَسِينَا وَمَا ‏ ‏نَخْشَى أَنْ يَكُونَ ‏ ‏جُنْدَبٌ ‏ ‏كَذَبَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ بِرَجُلٍ فِيمَنْ كَانَ قَبْلَكُمْ ‏ ‏خُرَاجٌ ‏ ‏فَذَكَرَ نَحْوَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b3dcbd6d-5066-5ef3-bcc6-fefd83e8b493', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '165', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سِمَاكٌ الْحَنَفِيُّ أَبُو زُمَيْلٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَبَّاسٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏خَيْبَرَ ‏ ‏أَقْبَلَ نَفَرٌ مِنْ ‏ ‏صَحَابَةِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا فُلَانٌ شَهِيدٌ فُلَانٌ شَهِيدٌ حَتَّى مَرُّوا عَلَى رَجُلٍ فَقَالُوا فُلَانٌ شَهِيدٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلَّا ‏ ‏إِنِّي رَأَيْتُهُ فِي النَّارِ فِي ‏ ‏بُرْدَةٍ ‏ ‏غَلَّهَا ‏ ‏أَوْ عَبَاءَةٍ ‏ ‏ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏ابْنَ الْخَطَّابِ ‏ ‏اذْهَبْ فَنَادِ فِي النَّاسِ أَنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ قَالَ فَخَرَجْتُ فَنَادَيْتُ أَلَا إِنَّهُ لَا يَدْخُلُ الْجَنَّةَ إِلَّا الْمُؤْمِنُونَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ad3a767e-b8df-5098-9591-a596d8956c29', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '166', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ زَيْدٍ الدُّؤَلِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي الْغَيْثِ ‏ ‏مَوْلَى ‏ ‏ابْنِ مُطِيعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَهَذَا حَدِيثُهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏خَيْبَرَ ‏ ‏فَفَتَحَ اللَّهُ عَلَيْنَا فَلَمْ نَغْنَمْ ذَهَبًا وَلَا ‏ ‏وَرِقًا ‏ ‏غَنِمْنَا الْمَتَاعَ وَالطَّعَامَ وَالثِّيَابَ ثُمَّ انْطَلَقْنَا إِلَى الْوَادِي وَمَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَبْدٌ لَهُ وَهَبَهُ لَهُ رَجُلٌ مِنْ ‏ ‏جُذَامَ ‏ ‏يُدْعَى ‏ ‏رِفَاعَةَ بْنَ زَيْدٍ ‏ ‏مِنْ ‏ ‏بَنِي الضُّبَيْبِ ‏ ‏فَلَمَّا نَزَلْنَا الْوَادِي قَامَ عَبْدُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَحُلُّ ‏ ‏رَحْلَهُ ‏ ‏فَرُمِيَ بِسَهْمٍ فَكَانَ فِيهِ ‏ ‏حَتْفُهُ ‏ ‏فَقُلْنَا هَنِيئًا لَهُ الشَّهَادَةُ يَا رَسُولَ اللَّهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلَّا وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏إِنَّ ‏ ‏الشَّمْلَةَ ‏ ‏لَتَلْتَهِبُ عَلَيْهِ نَارًا أَخَذَهَا مِنْ الْغَنَائِمِ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏لَمْ تُصِبْهَا الْمَقَاسِمُ قَالَ فَفَزِعَ النَّاسُ فَجَاءَ رَجُلٌ ‏ ‏بِشِرَاكٍ ‏ ‏أَوْ شِرَاكَيْنِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَصَبْتُ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شِرَاكٌ ‏ ‏مِنْ نَارٍ ‏ ‏أَوْ شِرَاكَانِ ‏ ‏مِنْ نَارٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('26f9cdaa-fc89-505e-848a-68a2dea43d95', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '167', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ الصَّوَّافِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏أَنَّ ‏ ‏الطُّفَيْلَ بْنَ عَمْرٍو الدَّوْسِيَّ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ هَلْ لَكَ فِي حِصْنٍ حَصِينٍ وَمَنْعَةٍ قَالَ حِصْنٌ كَانَ ‏ ‏لِدَوْسٍ ‏ ‏فِي الْجَاهِلِيَّةِ فَأَبَى ذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّذِي ‏ ‏ذَخَرَ ‏ ‏اللَّهُ ‏ ‏لِلْأَنْصَارِ ‏ ‏فَلَمَّا هَاجَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏هَاجَرَ إِلَيْهِ ‏ ‏الطُّفَيْلُ بْنُ عَمْرٍو ‏ ‏وَهَاجَرَ مَعَهُ رَجُلٌ مِنْ قَوْمِهِ ‏ ‏فَاجْتَوَوْا ‏ ‏الْمَدِينَةَ ‏ ‏فَمَرِضَ فَجَزِعَ فَأَخَذَ ‏ ‏مَشَاقِصَ ‏ ‏لَهُ فَقَطَعَ بِهَا ‏ ‏بَرَاجِمَهُ ‏ ‏فَشَخَبَتْ ‏ ‏يَدَاهُ حَتَّى مَاتَ فَرَآهُ ‏ ‏الطُّفَيْلُ بْنُ عَمْرٍو ‏ ‏فِي مَنَامِهِ فَرَآهُ وَهَيْئَتُهُ حَسَنَةٌ وَرَآهُ مُغَطِّيًا يَدَيْهِ فَقَالَ لَهُ مَا صَنَعَ بِكَ رَبُّكَ فَقَالَ غَفَرَ لِي بِهِجْرَتِي إِلَى نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا لِي أَرَاكَ مُغَطِّيًا يَدَيْكَ قَالَ قِيلَ لِي لَنْ نُصْلِحَ مِنْكَ مَا أَفْسَدْتَ فَقَصَّهَا ‏ ‏الطُّفَيْلُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ وَلِيَدَيْهِ فَاغْفِرْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a79dc0f2-760e-54f8-af55-e4cbb73ca562', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '168', '‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدَةَ الضَّبِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏وَأَبُو عَلْقَمَةَ الْفَرْوِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَلْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يَبْعَثُ رِيحًا مِنْ ‏ ‏الْيَمَنِ ‏ ‏أَلْيَنَ مِنْ الْحَرِيرِ فَلَا تَدَعُ أَحَدًا فِي قَلْبِهِ ‏ ‏قَالَ ‏ ‏أَبُو عَلْقَمَةَ ‏ ‏مِثْقَالُ حَبَّةٍ ‏ ‏و قَالَ ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏مِثْقَالُ ذَرَّةٍ ‏ ‏مِنْ إِيمَانٍ إِلَّا قَبَضَتْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e772b37-8156-5de8-87a6-97efbb322e22', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '169', '‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَادِرُوا بِالْأَعْمَالِ فِتَنًا كَقِطَعِ اللَّيْلِ الْمُظْلِمِ يُصْبِحُ الرَّجُلُ مُؤْمِنًا ‏ ‏وَيُمْسِي كَافِرًا أَوْ يُمْسِي مُؤْمِنًا وَيُصْبِحُ كَافِرًا يَبِيعُ دِينَهُ ‏ ‏بِعَرَضٍ ‏ ‏مِنْ الدُّنْيَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b13257b1-a2bd-555f-b16f-96c08efa04b8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '170', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏} ‏إِلَى آخِرِ الْآيَةِ جَلَسَ ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏فِي بَيْتِهِ وَقَالَ أَنَا مِنْ أَهْلِ النَّارِ وَاحْتَبَسَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏مَا شَأْنُ ‏ ‏ثَابِتٍ ‏ ‏اشْتَكَى ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏إِنَّهُ لَجَارِي وَمَا عَلِمْتُ لَهُ بِشَكْوَى قَالَ فَأَتَاهُ ‏ ‏سَعْدٌ ‏ ‏فَذَكَرَ لَهُ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ثَابِتٌ ‏ ‏أُنْزِلَتْ هَذِهِ الْآيَةُ وَلَقَدْ عَلِمْتُمْ أَنِّي مِنْ أَرْفَعِكُمْ صَوْتًا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنَا مِنْ أَهْلِ النَّارِ فَذَكَرَ ذَلِكَ ‏ ‏سَعْدٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ هُوَ مِنْ أَهْلِ الْجَنَّةِ ‏ ‏و حَدَّثَنَا ‏ ‏قَطَنُ بْنُ نُسَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ ‏ ‏خَطِيبَ ‏ ‏الْأَنْصَارِ ‏ ‏فَلَمَّا نَزَلَتْ هَذِهِ الْآيَةُ بِنَحْوِ حَدِيثِ ‏ ‏حَمَّادٍ ‏ ‏وَلَيْسَ فِي حَدِيثِهِ ذِكْرُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏و حَدَّثَنِيهِ ‏ ‏أَحْمَدُ بْنُ سَعِيدِ بْنِ صَخْرٍ الدَّارِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَبَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏} ‏وَلَمْ يَذْكُرْ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏فِي الْحَدِيثِ ‏ ‏و حَدَّثَنَا ‏ ‏هُرَيْمُ بْنُ عَبْدِ الْأَعْلَى الْأَسَدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَذْكُرُ عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ وَاقْتَصَّ الْحَدِيثَ وَلَمْ يَذْكُرْ ‏ ‏سَعْدَ بْنَ مُعَاذٍ ‏ ‏وَزَادَ فَكُنَّا ‏ ‏نَرَاهُ يَمْشِي بَيْنَ أَظْهُرِنَا رَجُلٌ مِنْ أَهْلِ الْجَنَّةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c42c6b2d-1780-583c-959f-fcb1e9cd7924', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '171', '‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ أُنَاسٌ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا رَسُولَ اللَّهِ أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ قَالَ ‏ ‏أَمَّا مَنْ أَحْسَنَ مِنْكُمْ فِي الْإِسْلَامِ فَلَا يُؤَاخَذُ بِهَا وَمَنْ أَسَاءَ أُخِذَ بِعَمَلِهِ فِي الْجَاهِلِيَّةِ وَالْإِسْلَامِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('d422905d-041d-5a7a-9ac0-107ef488169d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '172', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قُلْنَا يَا رَسُولَ اللَّهِ أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ قَالَ ‏ ‏مَنْ أَحْسَنَ فِي الْإِسْلَامِ لَمْ يُؤَاخَذْ بِمَا عَمِلَ فِي الْجَاهِلِيَّةِ وَمَنْ أَسَاءَ فِي الْإِسْلَامِ أُخِذَ بِالْأَوَّلِ وَالْآخِرِ ‏ ‏حَدَّثَنَا ‏ ‏مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b9c84159-336d-5100-bea0-cbe3e7cede56', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '173', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى الْعَنَزِيُّ ‏ ‏وَأَبُو مَعْنٍ الرَّقَاشِيُّ ‏ ‏وَإِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏أَبِي عَاصِمٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِابْنِ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ يَعْنِي أَبَا عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِمَاسَةَ الْمَهْرِيِّ ‏ ‏قَالَ ‏ ‏حَضَرْنَا ‏ ‏عَمْرَو بْنَ الْعَاصِ ‏ ‏وَهُوَ ‏ ‏فِي سِيَاقَةِ ‏ ‏الْمَوْتِ فَبَكَى طَوِيلًا وَحَوَّلَ وَجْهَهُ إِلَى الْجِدَارِ فَجَعَلَ ابْنُهُ يَقُولُ يَا أَبَتَاهُ أَمَا بَشَّرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَذَا أَمَا بَشَّرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَذَا قَالَ فَأَقْبَلَ بِوَجْهِهِ فَقَالَ إِنَّ أَفْضَلَ مَا نُعِدُّ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا رَسُولُ اللَّهِ ‏ ‏إِنِّي كُنْتُ عَلَى أَطْبَاقٍ ثَلَاثٍ لَقَدْ رَأَيْتُنِي وَمَا أَحَدٌ أَشَدَّ بُغْضًا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنِّي وَلَا أَحَبَّ إِلَيَّ أَنْ أَكُونَ قَدْ اسْتَمْكَنْتُ مِنْهُ فَقَتَلْتُهُ فَلَوْ مُتُّ عَلَى تِلْكَ الْحَالِ لَكُنْتُ مِنْ أَهْلِ النَّارِ فَلَمَّا جَعَلَ اللَّهُ الْإِسْلَامَ فِي قَلْبِي أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ ابْسُطْ يَمِينَكَ فَلْأُبَايِعْكَ فَبَسَطَ يَمِينَهُ قَالَ فَقَبَضْتُ يَدِي قَالَ مَا لَكَ يَا ‏ ‏عَمْرُو ‏ ‏قَالَ قُلْتُ أَرَدْتُ أَنْ أَشْتَرِطَ قَالَ تَشْتَرِطُ بِمَاذَا قُلْتُ أَنْ يُغْفَرَ لِي قَالَ ‏ ‏أَمَا عَلِمْتَ أَنَّ الْإِسْلَامَ يَهْدِمُ مَا كَانَ قَبْلَهُ وَأَنَّ الْهِجْرَةَ تَهْدِمُ مَا كَانَ قَبْلِهَا وَأَنَّ الْحَجَّ يَهْدِمُ مَا كَانَ قَبْلَهُ وَمَا كَانَ أَحَدٌ أَحَبَّ إِلَيَّ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا أَجَلَّ فِي عَيْنِي مِنْهُ وَمَا كُنْتُ أُطِيقُ أَنْ أَمْلَأَ عَيْنَيَّ مِنْهُ إِجْلَالًا لَهُ وَلَوْ سُئِلْتُ أَنْ أَصِفَهُ مَا أَطَقْتُ لِأَنِّي لَمْ أَكُنْ أَمْلَأُ عَيْنَيَّ مِنْهُ وَلَوْ مُتُّ عَلَى تِلْكَ الْحَالِ لَرَجَوْتُ أَنْ أَكُونَ مِنْ أَهْلِ الْجَنَّةِ ثُمَّ وَلِينَا أَشْيَاءَ مَا أَدْرِي مَا حَالِي فِيهَا فَإِذَا أَنَا مُتُّ فَلَا تَصْحَبْنِي نَائِحَةٌ وَلَا نَارٌ فَإِذَا دَفَنْتُمُونِي ‏ ‏فَشُنُّوا ‏ ‏عَلَيَّ التُّرَابَ شَنًّا ثُمَّ أَقِيمُوا حَوْلَ قَبْرِي قَدْرَ مَا تُنْحَرُ ‏ ‏جَزُورٌ ‏ ‏وَيُقْسَمُ لَحْمُهَا حَتَّى أَسْتَأْنِسَ بِكُمْ وَأَنْظُرَ مَاذَا أُرَاجِعُ بِهِ رُسُلَ رَبِّي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('b2af38ba-2ecd-5d0c-985d-5e731b7890e4', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '174', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمِ بْنِ مَيْمُونٍ ‏ ‏وَإِبْرَاهِيمُ بْنُ دِينَارٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَجَّاجٌ وَهُوَ ابْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ مُسْلِمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ نَاسًا مِنْ أَهْلِ الشِّرْكِ قَتَلُوا فَأَكْثَرُوا وَزَنَوْا فَأَكْثَرُوا ثُمَّ أَتَوْا ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّ الَّذِي تَقُولُ وَتَدْعُو لَحَسَنٌ وَلَوْ تُخْبِرُنَا أَنَّ لِمَا عَمِلْنَا كَفَّارَةً فَنَزَلَ ‏ { ‏وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ ‏ ‏أَثَامًا ‏ } ‏وَنَزَلَ ‏ { ‏يَا ‏ ‏عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا ‏ ‏تَقْنَطُوا ‏ ‏مِنْ رَحْمَةِ اللَّهِ ‏}', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1d839354-374d-5627-b9c4-bf78abdb998c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '175', '‏ ‏حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتَ أُمُورًا كُنْتُ ‏ ‏أَتَحَنَّثُ ‏ ‏بِهَا فِي الْجَاهِلِيَّةِ هَلْ لِي فِيهَا مِنْ شَيْءٍ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏مِنْ خَيْرٍ ‏ ‏وَالتَّحَنُّثُ التَّعَبُّدُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('308a0b62-5fc9-5175-8b32-119d8c025948', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '176', '‏ ‏و حَدَّثَنَا ‏ ‏حَسَنٌ الْحُلْوَانِيُّ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَ ‏ ‏الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏وَقَالَ ‏ ‏عَبْدٌ ‏ ‏حَدَّثَنِي ‏ ‏يَعْقُوبُ وَهُوَ ابْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ قَالَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْ رَسُولَ اللَّهِ أَرَأَيْتَ أُمُورًا كُنْتُ ‏ ‏أَتَحَنَّثُ ‏ ‏بِهَا فِي الْجَاهِلِيَّةِ مِنْ صَدَقَةٍ أَوْ ‏ ‏عَتَاقَةٍ ‏ ‏أَوْ صِلَةِ رَحِمٍ أَفِيهَا أَجْرٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏مِنْ خَيْرٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('71478433-02d9-5abf-b1cf-f0e1ae51a972', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '177', '‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَشْيَاءَ كُنْتُ أَفْعَلُهَا فِي الْجَاهِلِيَّةِ ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏يَعْنِي ‏ ‏أَتَبَرَّرُ ‏ ‏بِهَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمْتَ عَلَى مَا ‏ ‏أَسْلَفْتَ ‏ ‏لَكَ مِنْ الْخَيْرِ قُلْتُ فَوَاللَّهِ لَا أَدَعُ شَيْئًا صَنَعْتُهُ فِي الْجَاهِلِيَّةِ إِلَّا فَعَلْتُ فِي الْإِسْلَامِ مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏حَكِيمَ بْنَ حِزَامٍ ‏ ‏أَعْتَقَ فِي الْجَاهِلِيَّةِ مِائَةَ رَقَبَةٍ وَحَمَلَ عَلَى مِائَةِ بَعِيرٍ ثُمَّ أَعْتَقَ فِي الْإِسْلَامِ مِائَةَ رَقَبَةٍ وَحَمَلَ عَلَى مِائَةِ بَعِيرٍ ثُمَّ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِهِمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('397e8aa6-453a-5fe3-8a8e-0f14c8b171c6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '178', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ إِدْرِيسَ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏الَّذِينَ آمَنُوا وَلَمْ ‏ ‏يَلْبِسُوا ‏ ‏إِيمَانَهُمْ ‏ ‏بِظُلْمٍ ‏ } ‏شَقَّ ذَلِكَ عَلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالُوا أَيُّنَا لَا يَظْلِمُ نَفْسَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ هُوَ كَمَا تَظُنُّونَ إِنَّمَا هُوَ كَمَا قَالَ ‏ ‏لُقْمَانُ ‏ ‏لِابْنِهِ ‏ { ‏يَا بُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ ‏} ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَعَلِيُّ بْنُ خَشْرَمٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏عِيسَى وَهُوَ ابْنُ يُونُسَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مِنْجَابُ بْنُ الْحَارِثِ التَّمِيمِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ مُسْهِرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏قَالَ ‏ ‏أَبُو كُرَيْبٍ ‏ ‏قَالَ ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏حَدَّثَنِيهِ ‏ ‏أَوَّلًا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبَانَ بْنِ تَغْلِبَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏ثُمَّ ‏ ‏سَمِعْتُهُ مِنْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e460c3b3-be4c-5209-b238-30114072e2ac', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '179', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مِنْهَالٍ الضَّرِيرُ ‏ ‏وَأُمَيَّةُ بْنُ بِسْطَامَ الْعَيْشِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِأُمَيَّةَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ وَهُوَ ابْنُ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏لِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الْأَرْضِ وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ فَيَغْفِرُ لِمَنْ يَشَاءُ وَيُعَذِّبُ مَنْ يَشَاءُ وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏} ‏قَالَ فَاشْتَدَّ ذَلِكَ عَلَى ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ بَرَكُوا عَلَى الرُّكَبِ فَقَالُوا أَيْ رَسُولَ اللَّهِ كُلِّفْنَا مِنْ الْأَعْمَالِ مَا نُطِيقُ الصَّلَاةَ وَالصِّيَامَ وَالْجِهَادَ وَالصَّدَقَةَ وَقَدْ أُنْزِلَتْ عَلَيْكَ هَذِهِ الْآيَةُ وَلَا نُطِيقُهَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتُرِيدُونَ أَنْ تَقُولُوا كَمَا قَالَ أَهْلُ الْكِتَابَيْنِ مِنْ قَبْلِكُمْ سَمِعْنَا وَعَصَيْنَا بَلْ قُولُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ قَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ فَلَمَّا اقْتَرَأَهَا الْقَوْمُ ذَلَّتْ بِهَا أَلْسِنَتُهُمْ فَأَنْزَلَ اللَّهُ فِي ‏ ‏إِثْرِهَا ‏ { ‏آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ‏} ‏فَلَمَّا فَعَلُوا ذَلِكَ نَسَخَهَا اللَّهُ تَعَالَى فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا ‏ ‏وُسْعَهَا ‏ ‏لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا ‏ ‏إِصْرًا ‏ ‏كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏} ‏قَالَ نَعَمْ ‏ { ‏رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ‏} ‏قَالَ نَعَمْ ‏ { ‏وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ ‏} ‏قَالَ نَعَمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('99cc4f97-1d9e-5129-9aa9-ca3525060133', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '180', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏آدَمَ بْنِ سُلَيْمَانَ ‏ ‏مَوْلَى ‏ ‏خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏وَإِنْ تُبْدُوا مَا فِي أَنْفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُمْ بِهِ اللَّهُ ‏} ‏قَالَ دَخَلَ قُلُوبَهُمْ مِنْهَا شَيْءٌ لَمْ يَدْخُلْ قُلُوبَهُمْ مِنْ شَيْءٍ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُولُوا سَمِعْنَا وَأَطَعْنَا وَسَلَّمْنَا قَالَ فَأَلْقَى اللَّهُ الْإِيمَانَ فِي قُلُوبِهِمْ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا ‏ ‏وُسْعَهَا ‏ ‏لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا ‏} ‏قَالَ قَدْ فَعَلْتُ ‏ { ‏رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا ‏ ‏إِصْرًا ‏ ‏كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا ‏} ‏قَالَ قَدْ فَعَلْتُ ‏ { ‏وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا ‏} ‏قَالَ قَدْ فَعَلْتُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0f288eaa-d441-5be5-9910-0465de9a6290', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '181', '‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ مَنْصُورٍ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وُمُحَمَّدُ بْنُ عُبَيْدٍ الْغُبَرِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِسَعِيدٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ ‏ ‏تَجَاوَزَ ‏ ‏لِأُمَّتِي مَا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ يَتَكَلَّمُوا أَوْ يَعْمَلُوا بِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8c9270cd-5ab2-5662-bab9-4f05900909e8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '182', '‏ ‏حَدَّثَنَا ‏ ‏عَمْرٌو النَّاقِدُ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ مُسْهِرٍ ‏ ‏وَعَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ الْمُثَنَّى ‏ ‏وَابْنُ بَشَّارٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏تَجَاوَزَ ‏ ‏لِأُمَّتِي عَمَّا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ تَعْمَلْ أَوْ تَكَلَّمْ بِهِ ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏وَهِشَامٌ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏إِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏أَخْبَرَنَا ‏ ‏الْحُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏شَيْبَانَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
