insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2e46637c-7719-5a64-aecd-d516097bd8c0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '184', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ ‏ ‏وَابْنُ حُجْرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ وَهُوَ ابْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِذَا هَمَّ عَبْدِي بِحَسَنَةٍ وَلَمْ يَعْمَلْهَا كَتَبْتُهَا لَهُ حَسَنَةً فَإِنْ عَمِلَهَا كَتَبْتُهَا عَشْرَ حَسَنَاتٍ إِلَى سَبْعِ مِائَةِ ضِعْفٍ وَإِذَا هَمَّ بِسَيِّئَةٍ وَلَمْ يَعْمَلْهَا لَمْ أَكْتُبْهَا عَلَيْهِ فَإِنْ عَمِلَهَا كَتَبْتُهَا سَيِّئَةً وَاحِدَةً ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a51163c8-d48d-563f-98c3-a9ab7c88e4ef', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '185', '‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏قَالَ هَذَا مَا حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ أَحَادِيثَ مِنْهَا قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِذَا ‏ ‏تَحَدَّثَ ‏ ‏عَبْدِي بِأَنْ يَعْمَلَ حَسَنَةً فَأَنَا أَكْتُبُهَا لَهُ حَسَنَةً مَا لَمْ يَعْمَلْ فَإِذَا عَمِلَهَا فَأَنَا أَكْتُبُهَا بِعَشْرِ أَمْثَالِهَا وَإِذَا ‏ ‏تَحَدَّثَ ‏ ‏بِأَنْ يَعْمَلَ سَيِّئَةً فَأَنَا أَغْفِرُهَا لَهُ مَا لَمْ يَعْمَلْهَا فَإِذَا عَمِلَهَا فَأَنَا أَكْتُبُهَا لَهُ بِمِثْلِهَا وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ الْمَلَائِكَةُ رَبِّ ذَاكَ عَبْدُكَ يُرِيدُ أَنْ يَعْمَلَ سَيِّئَةً وَهُوَ أَبْصَرُ بِهِ فَقَالَ ارْقُبُوهُ فَإِنْ عَمِلَهَا فَاكْتُبُوهَا لَهُ بِمِثْلِهَا وَإِنْ تَرَكَهَا فَاكْتُبُوهَا لَهُ حَسَنَةً إِنَّمَا تَرَكَهَا مِنْ جَرَّايَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَحْسَنَ أَحَدُكُمْ إِسْلَامَهُ فَكُلُّ حَسَنَةٍ يَعْمَلُهَا تُكْتَبُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ وَكُلُّ سَيِّئَةٍ يَعْمَلُهَا تُكْتَبُ بِمِثْلِهَا حَتَّى يَلْقَى اللَّهَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('1027e21c-c5fe-5b22-bc9b-cc94d99eecd1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '186', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةً وَمَنْ هَمَّ بِحَسَنَةٍ فَعَمِلَهَا كُتِبَتْ لَهُ عَشْرًا إِلَى سَبْعِ مِائَةِ ضِعْفٍ وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا لَمْ تُكْتَبْ وَإِنْ عَمِلَهَا كُتِبَتْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('cd5e27cb-495b-576b-bda2-5087751cf590', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '187', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏عَنْ ‏ ‏الْجَعْدِ أَبِي عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو رَجَاءٍ الْعُطَارِدِيُّ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَرْوِي عَنْ رَبِّهِ تَبَارَكَ وَتَعَالَى قَالَ ‏ ‏إِنَّ اللَّهَ كَتَبَ الْحَسَنَاتِ وَالسَّيِّئَاتِ ثُمَّ بَيَّنَ ذَلِكَ فَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ عَزَّ وَجَلَّ عِنْدَهُ عَشْرَ حَسَنَاتٍ إِلَى سَبْعِ مِائَةِ ضِعْفٍ إِلَى أَضْعَافٍ كَثِيرَةٍ وَإِنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا كَتَبَهَا اللَّهُ عِنْدَهُ حَسَنَةً كَامِلَةً وَإِنْ هَمَّ بِهَا فَعَمِلَهَا كَتَبَهَا اللَّهُ سَيِّئَةً وَاحِدَةً ‏ ‏و حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏الْجَعْدِ أَبِي عُثْمَانَ ‏ ‏فِي هَذَا الْإِسْنَادِ بِمَعْنَى حَدِيثِ ‏ ‏عَبْدِ الْوَارِثِ ‏ ‏وَزَادَ وَمَحَاهَا اللَّهُ وَلَا يَهْلِكُ عَلَى اللَّهِ إِلَّا هَالِكٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('74e30182-49cd-52fe-b694-17d7e8d68392', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '188', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ نَاسٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلُوهُ إِنَّا نَجِدُ فِي أَنْفُسِنَا مَا يَتَعَاظَمُ أَحَدُنَا أَنْ يَتَكَلَّمَ بِهِ قَالَ ‏ ‏وَقَدْ وَجَدْتُمُوهُ قَالُوا نَعَمْ قَالَ ذَاكَ ‏ ‏صَرِيحُ ‏ ‏الْإِيمَانِ ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَمْرِو بْنِ جَبَلَةَ بْنِ أَبِي رَوَّادٍ ‏ ‏وَأَبُو بَكْرِ بْنُ إِسْحَقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو الْجَوَّابِ ‏ ‏عَنْ ‏ ‏عَمَّارِ بْنِ رُزَيْقٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا الْحَدِيثِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('45a5c3e6-9b78-5684-9ff7-c029e1123dba', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '189', '‏ ‏حَدَّثَنَا ‏ ‏يُوسُفُ بْنُ يَعْقُوبَ الصَّفَّارُ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ عَثَّامٍ ‏ ‏عَنْ ‏ ‏سُعَيْرِ بْنِ الْخِمْسِ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْوَسْوَسَةِ قَالَ ‏ ‏تِلْكَ ‏ ‏مَحْضُ ‏ ‏الْإِيمَانِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('e407221a-1242-52cb-b935-2e05a7b6325d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '190', '‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَمُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِهَارُونَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ النَّاسُ يَتَسَاءَلُونَ حَتَّى يُقَالَ هَذَا خَلَقَ اللَّهُ الْخَلْقَ فَمَنْ خَلَقَ اللَّهَ فَمَنْ وَجَدَ مِنْ ذَلِكَ شَيْئًا فَلْيَقُلْ آمَنْتُ بِاللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏مَحْمُودُ بْنُ غَيْلَانَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ الْمُؤَدِّبُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏بِهَذَا الْإِسْنَادِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَأْتِي الشَّيْطَانُ أَحَدَكُمْ فَيَقُولُ مَنْ خَلَقَ السَّمَاءَ مَنْ خَلَقَ الْأَرْضَ فَيَقُولُ اللَّهُ ثُمَّ ذَكَرَ بِمِثْلِهِ وَزَادَ وَرُسُلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f24da671-c3b6-51cd-82e7-aec06706c8d6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '191', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏يَعْقُوبَ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي الشَّيْطَانُ أَحَدَكُمْ فَيَقُولَ مَنْ خَلَقَ كَذَا وَكَذَا حَتَّى يَقُولَ لَهُ مَنْ خَلَقَ رَبَّكَ فَإِذَا بَلَغَ ذَلِكَ فَلْيَسْتَعِذْ بِاللَّهِ وَلْيَنْتَهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ شُعَيْبِ بْنِ اللَّيْثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْتِي الْعَبْدَ الشَّيْطَانُ فَيَقُولُ مَنْ خَلَقَ كَذَا وَكَذَا مِثْلَ حَدِيثِ ‏ ‏ابْنِ أَخِي ابْنِ شِهَابٍ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('c1d94923-2270-5385-93e0-e22cf54ad99e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '192', '‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْوَارِثِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ النَّاسُ يَسْأَلُونَكُمْ عَنْ الْعِلْمِ حَتَّى يَقُولُوا هَذَا اللَّهُ خَلَقَنَا فَمَنْ خَلَقَ اللَّهَ قَالَ وَهُوَ آخِذٌ بِيَدِ رَجُلٍ فَقَالَ صَدَقَ اللَّهُ وَرَسُولُهُ قَدْ سَأَلَنِي اثْنَانِ وَهَذَا الثَّالِثُ أَوْ قَالَ سَأَلَنِي وَاحِدٌ وَهَذَا الثَّانِي ‏ ‏و حَدَّثَنِيهِ ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَيَعْقُوبُ الدَّوْرَقِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ وَهُوَ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏لَا يَزَالُ النَّاسُ بِمِثْلِ حَدِيثِ ‏ ‏عَبْدِ الْوَارِثِ ‏ ‏غَيْرَ أَنَّهُ لَمْ يَذْكُرْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْإِسْنَادِ وَلَكِنْ قَدْ قَالَ فِي آخِرِ الْحَدِيثِ صَدَقَ اللَّهُ وَرَسُولُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f5a6b307-68a9-5014-ac3d-7ce4b6bc5079', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '193', '‏ ‏و حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ الرُّومِيِّ ‏ ‏حَدَّثَنَا ‏ ‏النَّضْرُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ وَهُوَ ابْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُونَ يَسْأَلُونَكَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏حَتَّى يَقُولُوا هَذَا اللَّهُ فَمَنْ خَلَقَ اللَّهَ قَالَ فَبَيْنَا أَنَا فِي الْمَسْجِدِ إِذْ جَاءَنِي نَاسٌ مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏فَقَالُوا يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏هَذَا اللَّهُ فَمَنْ خَلَقَ اللَّهَ قَالَ فَأَخَذَ حَصًى بِكَفِّهِ فَرَمَاهُمْ ثُمَّ قَالَ قُومُوا قُومُوا صَدَقَ خَلِيلِي ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('bf1470ad-3a58-50e4-a8ab-cf7365dcde20', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '194', '‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَسْأَلَنَّكُمْ النَّاسُ عَنْ كُلِّ شَيْءٍ حَتَّى يَقُولُوا اللَّهُ خَلَقَ كُلَّ شَيْءٍ فَمَنْ خَلَقَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fba6efda-8f14-5a38-88a8-8a12d1d29b03', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '195', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرِ بْنِ زُرَارَةَ الْحَضْرَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏مُخْتَارِ بْنِ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِنَّ أُمَّتَكَ لَا يَزَالُونَ يَقُولُونَ مَا كَذَا مَا كَذَا حَتَّى يَقُولُوا هَذَا اللَّهُ خَلَقَ الْخَلْقَ فَمَنْ خَلَقَ اللَّهَ ‏ ‏حَدَّثَنَاه ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏الْمُخْتَارِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَذَا الْحَدِيثِ ‏ ‏غَيْرَ أَنَّ ‏ ‏إِسْحَقَ ‏ ‏لَمْ يَذْكُرْ قَالَ قَالَ اللَّهُ إِنَّ أُمَّتَكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8c89b8b9-94bb-554f-b7e5-ef5fd7874f91', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '196', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعَلِيُّ بْنُ حُجْرٍ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَعِيلُ بْنُ جَعْفَرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْعَلَاءُ وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ ‏ ‏مَوْلَى ‏ ‏الْحُرَقَةِ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ السَّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏اقْتَطَعَ ‏ ‏حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ فَقَالَ لَهُ رَجُلٌ وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ قَالَ وَإِنْ ‏ ‏قَضِيبًا ‏ ‏مِنْ ‏ ‏أَرَاكٍ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏وَهَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي أُسَامَةَ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَخَاهُ ‏ ‏عَبْدَ اللَّهِ بْنَ كَعْبٍ ‏ ‏يُحَدِّثُ أَنَّ ‏ ‏أَبَا أُمَامَةَ الْحَارِثِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('f48abdc3-1ec0-5a11-8fa8-251869ce2bf3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '197', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ الْحَنْظَلِيُّ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏أَخْبَرَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينِ ‏ ‏صَبْرٍ ‏ ‏يَقْتَطِعُ ‏ ‏بِهَا مَالَ امْرِئٍ مُسْلِمٍ هُوَ فِيهَا فَاجِرٌ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ ‏ ‏قَالَ فَدَخَلَ ‏ ‏الْأَشْعَثُ بْنُ قَيْسٍ ‏ ‏فَقَالَ مَا يُحَدِّثُكُمْ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏قَالُوا كَذَا وَكَذَا قَالَ صَدَقَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏فِيَّ نَزَلَتْ كَانَ بَيْنِي وَبَيْنَ ‏ ‏رَجُلٍ ‏ ‏أَرْضٌ ‏ ‏بِالْيَمَنِ ‏ ‏فَخَاصَمْتُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏هَلْ لَكَ بَيِّنَةٌ فَقُلْتُ لَا قَالَ فَيَمِينُهُ قُلْتُ إِذَنْ يَحْلِفُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ مَنْ حَلَفَ عَلَى يَمِينِ ‏ ‏صَبْرٍ ‏ ‏يَقْتَطِعُ ‏ ‏بِهَا مَالَ امْرِئٍ مُسْلِمٍ هُوَ فِيهَا فَاجِرٌ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ فَنَزَلَتْ ‏ { ‏إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ يَسْتَحِقُّ بِهَا مَالًا هُوَ فِيهَا فَاجِرٌ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ ثُمَّ ذَكَرَ نَحْوَ حَدِيثِ ‏ ‏الْأَعْمَشِ ‏ ‏غَيْرَ أَنَّهُ قَالَ كَانَتْ بَيْنِي وَبَيْنَ ‏ ‏رَجُلٍ ‏ ‏خُصُومَةٌ فِي بِئْرٍ ‏ ‏فَاخْتَصَمْنَا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ شَاهِدَاكَ أَوْ يَمِينُهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5a23d03f-8b7a-5dc8-a3f5-a55e3d5ef4e2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '198', '‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ الْمَكِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَامِعِ بْنِ أَبِي رَاشِدٍ ‏ ‏وَعَبْدِ الْمَلِكِ بْنِ أَعْيَنَ ‏ ‏سَمِعَا ‏ ‏شَقِيقَ بْنَ سَلَمَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏يَقُولُا ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ حَلَفَ عَلَى مَالِ امْرِئٍ مُسْلِمٍ بِغَيْرِ حَقِّهِ لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏ثُمَّ قَرَأَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِصْدَاقَهُ مِنْ كِتَابِ اللَّهِ ‏ { ‏إِنَّ الَّذِينَ يَشْتَرُونَ بِعَهْدِ اللَّهِ وَأَيْمَانِهِمْ ثَمَنًا قَلِيلًا ‏} ‏إِلَى آخِرِ الْآيَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36bf8a9c-f8d0-5a35-9e6c-61d2800ee3a2', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '199', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَهَنَّادُ بْنُ السَّرِيِّ ‏ ‏وَأَبُو عَاصِمٍ الْحَنَفِيُّ ‏ ‏وَاللَّفْظُ ‏ ‏لِقُتَيْبَةَ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَائِلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ مِنْ ‏ ‏حَضْرَمَوْتَ ‏ ‏وَرَجُلٌ مِنْ ‏ ‏كِنْدَةَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏الْحَضْرَمِيُّ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ هَذَا قَدْ غَلَبَنِي عَلَى أَرْضٍ لِي كَانَتْ لِأَبِي فَقَالَ الْكِنْدِيُّ هِيَ أَرْضِي فِي يَدِي أَزْرَعُهَا لَيْسَ لَهُ فِيهَا حَقٌّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْحَضْرَمِيِّ أَلَكَ ‏ ‏بَيِّنَةٌ ‏ ‏قَالَ لَا قَالَ فَلَكَ يَمِينُهُ قَالَ يَا رَسُولَ اللَّهِ إِنَّ الرَّجُلَ فَاجِرٌ لَا يُبَالِي عَلَى مَا حَلَفَ عَلَيْهِ وَلَيْسَ يَتَوَرَّعُ مِنْ شَيْءٍ فَقَالَ لَيْسَ لَكَ مِنْهُ إِلَّا ذَلِكَ فَانْطَلَقَ لِيَحْلِفَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا أَدْبَرَ ‏ ‏أَمَا لَئِنْ حَلَفَ عَلَى مَالِهِ لِيَأْكُلَهُ ظُلْمًا لَيَلْقَيَنَّ اللَّهَ وَهُوَ عَنْهُ مُعْرِضٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8b60a50f-528d-575b-bee0-291e89f9cdfa', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '200', '‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏أَبِي الْوَلِيدِ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَائِلٍ ‏ ‏عَنْ ‏ ‏وَائِلِ بْنِ حُجْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَاهُ رَجُلَانِ يَخْتَصِمَانِ فِي أَرْضٍ فَقَالَ أَحَدُهُمَا إِنَّ هَذَا ‏ ‏انْتَزَى ‏ ‏عَلَى أَرْضِي يَا رَسُولَ اللَّهِ فِي الْجَاهِلِيَّةِ وَهُوَ ‏ ‏امْرُؤُ الْقَيْسِ بْنُ عَابِسٍ الْكِنْدِيُّ ‏ ‏وَخَصْمُهُ ‏ ‏رَبِيعَةُ بْنُ عِبْدَانَ ‏ ‏قَالَ ‏ ‏بَيِّنَتُكَ ‏ ‏قَالَ لَيْسَ لِي بَيِّنَةٌ قَالَ يَمِينُهُ قَالَ إِذَنْ يَذْهَبُ بِهَا قَالَ لَيْسَ لَكَ إِلَّا ذَاكَ قَالَ فَلَمَّا قَامَ لِيَحْلِفَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏اقْتَطَعَ ‏ ‏أَرْضًا ظَالِمًا لَقِيَ اللَّهَ وَهُوَ عَلَيْهِ غَضْبَانُ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏فِي رِوَايَتِهِ ‏ ‏رَبِيعَةُ بْنُ عَيْدَانَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da42d459-3c16-501b-8dd8-a7fbaa6e5ec8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '201', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ مَخْلَدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَرَأَيْتَ إِنْ جَاءَ رَجُلٌ يُرِيدُ أَخْذَ مَالِي قَالَ فَلَا تُعْطِهِ مَالَكَ قَالَ أَرَأَيْتَ إِنْ قَاتَلَنِي قَالَ قَاتِلْهُ قَالَ أَرَأَيْتَ إِنْ قَتَلَنِي قَالَ فَأَنْتَ شَهِيدٌ قَالَ أَرَأَيْتَ إِنْ قَتَلْتُهُ قَالَ هُوَ فِي النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('5b3afb4e-25ef-5f49-84d2-8801d2395f44', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '202', '‏ ‏حَدَّثَنِي ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏وَإِسْحَقُ بْنُ مَنْصُورٍ ‏ ‏وَمُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَأَلْفَاظُهُمْ مُتَقَارِبَةٌ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ الْأَحْوَلُ ‏ ‏أَنَّ ‏ ‏ثَابِتًا ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ لَمَّا كَانَ بَيْنَ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏وَبَيْنَ ‏ ‏عَنْبَسَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏مَا كَانَ ‏ ‏تَيَسَّرُوا ‏ ‏لِلْقِتَالِ فَرَكِبَ ‏ ‏خَالِدُ بْنُ الْعَاصِ ‏ ‏إِلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرٍو ‏ ‏فَوَعَظَهُ ‏ ‏خَالِدٌ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قُتِلَ دُونَ مَالِهِ فَهُوَ شَهِيدٌ ‏ ‏و حَدَّثَنِيهِ ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عُثْمَانَ النَّوْفَلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fa462bcb-9ca1-547a-af8e-4b9937119a50', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '203', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏عَادَ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏مَعْقِلَ بْنَ يَسَارٍ الْمُزنِيَّ ‏ ‏فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ قَالَ ‏ ‏مَعْقِلٌ ‏ ‏إِنِّي مُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ عَلِمْتُ أَنَّ لِي حَيَاةً مَا حَدَّثْتُكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ ‏ ‏يَسْتَرْعِيهِ ‏ ‏اللَّهُ رَعِيَّةً يَمُوتُ يَوْمَ يَمُوتُ وَهُوَ غَاشٌّ لِرَعِيَّتِهِ إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2a56e33d-fc9e-5b74-86e9-5be91a4a7291', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '204', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏عَلَى ‏ ‏مَعْقَلِ بْنِ يَسَارٍ ‏ ‏وَهُوَ وَجِعٌ فَسَأَلَهُ فَقَالَ إِنِّي مُحَدِّثُكَ حَدِيثًا لَمْ أَكُنْ حَدَّثْتُكَهُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَسْتَرْعِي ‏ ‏اللَّهُ عَبْدًا رَعِيَّةً يَمُوتُ حِينَ يَمُوتُ وَهُوَ غَاشٌّ لَهَا إِلَّا حَرَّمَ اللَّهُ عَلَيْهِ الْجَنَّةَ ‏ ‏قَالَ أَلَّا كُنْتَ حَدَّثْتَنِي هَذَا قَبْلَ الْيَوْمِ قَالَ مَا حَدَّثْتُكَ أَوْ لَمْ أَكُنْ لَأُحَدِّثَكَ ‏ ‏و حَدَّثَنِي ‏ ‏الْقَاسِمُ بْنُ زَكَرِيَّاءَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ يَعْنِي الْجُعْفِيَّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ قَالَ ‏ ‏الْحَسَنُ ‏ ‏كُنَّا عِنْدَ ‏ ‏مَعْقِلِ بْنِ يَسَارٍ ‏ ‏نَعُودُهُ فَجَاءَ ‏ ‏عُبَيْدُ اللَّهِ بْنُ زِيَادٍ ‏ ‏فَقَالَ لَهُ ‏ ‏مَعْقِلٌ ‏ ‏إِنِّي سَأُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ذَكَرَ بِمَعْنَى حَدِيثِهِمَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('fc0e5430-fe85-581e-9955-2ad218d93f79', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '205', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو غَسَّانَ الْمِسْمَعِيُّ ‏ ‏وَمُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ الْآخَرَانِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏أَنَّ ‏ ‏عُبَيْدَ اللَّهِ بْنَ زِيَادٍ ‏ ‏عَادَ ‏ ‏مَعْقِلَ بْنَ يَسَارٍ ‏ ‏فِي مَرَضِهِ فَقَالَ لَهُ ‏ ‏مَعْقِلٌ ‏ ‏إِنِّي مُحَدِّثُكَ بِحَدِيثٍ لَوْلَا أَنِّي فِي الْمَوْتِ لَمْ أُحَدِّثْكَ بِهِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ أَمِيرٍ يَلِي أَمْرَ الْمُسْلِمِينَ ثُمَّ لَا ‏ ‏يَجْهَدُ ‏ ‏لَهُمْ وَيَنْصَحُ إِلَّا لَمْ يَدْخُلْ مَعَهُمْ الْجَنَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('40806d53-65c7-5673-99e9-a4e7a5122478', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '206', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَهْبٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثَيْنِ قَدْ رَأَيْتُ أَحَدَهُمَا وَأَنَا أَنْتَظِرُ الْآخَرَ حَدَّثَنَا ‏ ‏أَنَّ الْأَمَانَةَ نَزَلَتْ فِي جَذْرِ قُلُوبِ الرِّجَالِ ثُمَّ نَزَلَ الْقُرْآنُ فَعَلِمُوا مِنْ الْقُرْآنِ وَعَلِمُوا مِنْ السُّنَّةِ ‏ ‏ثُمَّ حَدَّثَنَا عَنْ رَفْعِ الْأَمَانَةِ قَالَ ‏ ‏يَنَامُ الرَّجُلُ النَّوْمَةَ فَتُقْبَضُ الْأَمَانَةُ مِنْ قَلْبِهِ فَيَظَلُّ أَثَرُهَا مِثْلَ ‏ ‏الْوَكْتِ ‏ ‏ثُمَّ يَنَامُ النَّوْمَةَ فَتُقْبَضُ الْأَمَانَةُ مِنْ قَلْبِهِ فَيَظَلُّ أَثَرُهَا مِثْلَ ‏ ‏الْمَجْلِ ‏ ‏كَجَمْرٍ دَحْرَجْتَهُ عَلَى رِجْلِكَ ‏ ‏فَنَفِطَ ‏ ‏فَتَرَاهُ ‏ ‏مُنْتَبِرًا ‏ ‏وَلَيْسَ فِيهِ شَيْءٌ ثُمَّ أَخَذَ حَصًى فَدَحْرَجَهُ عَلَى رِجْلِهِ فَيُصْبِحُ النَّاسُ يَتَبَايَعُونَ لَا يَكَادُ أَحَدٌ يُؤَدِّي الْأَمَانَةَ حَتَّى يُقَالَ إِنَّ فِي بَنِي فُلَانٍ رَجُلًا أَمِينًا حَتَّى يُقَالَ لِلرَّجُلِ مَا ‏ ‏أَجْلَدَهُ ‏ ‏مَا أَظْرَفَهُ مَا أَعْقَلَهُ وَمَا فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ وَلَقَدْ أَتَى عَلَيَّ زَمَانٌ وَمَا أُبَالِي أَيَّكُمْ ‏ ‏بَايَعْتُ ‏ ‏لَئِنْ كَانَ مُسْلِمًا ‏ ‏لَيَرُدَّنَّهُ ‏ ‏عَلَيَّ دِينُهُ وَلَئِنْ كَانَ نَصْرَانِيًّا أَوْ يَهُودِيًّا لَيَرُدَّنَّهُ عَلَيَّ ‏ ‏سَاعِيهِ ‏ ‏وَأَمَّا الْيَوْمَ فَمَا كُنْتُ لِأُبَايِعَ مِنْكُمْ إِلَّا فُلَانًا وَفُلَانًا ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏وَوَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ يُونُسَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏مِثْلَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('0e6fefa1-5b88-5a0c-aedc-53df19b8a050', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '207', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ يَعْنِي سُلَيْمَانَ بْنَ حَيَّانَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ طَارِقٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏عُمَرَ ‏ ‏فَقَالَ أَيُّكُمْ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ الْفِتَنَ فَقَالَ قَوْمٌ نَحْنُ سَمِعْنَاهُ فَقَالَ لَعَلَّكُمْ تَعْنُونَ ‏ ‏فِتْنَةَ ‏ ‏الرَّجُلِ فِي أَهْلِهِ وَجَارِهِ قَالُوا أَجَلْ قَالَ تِلْكَ تُكَفِّرُهَا الصَّلَاةُ وَالصِّيَامُ وَالصَّدَقَةُ وَلَكِنْ أَيُّكُمْ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ الْفِتَنَ الَّتِي ‏ ‏تَمُوجُ ‏ ‏مَوْجَ الْبَحْرِ قَالَ ‏ ‏حُذَيْفَةُ ‏ ‏فَأَسْكَتَ الْقَوْمُ فَقُلْتُ أَنَا قَالَ أَنْتَ ‏ ‏لِلَّهِ أَبُوكَ ‏ ‏قَالَ ‏ ‏حُذَيْفَةُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تُعْرَضُ الْفِتَنُ عَلَى الْقُلُوبِ كَالْحَصِيرِ عُودًا عُودًا فَأَيُّ قَلْبٍ ‏ ‏أُشْرِبَهَا ‏ ‏نُكِتَ ‏ ‏فِيهِ نُكْتَةٌ سَوْدَاءُ وَأَيُّ قَلْبٍ ‏ ‏أَنْكَرَهَا ‏ ‏نُكِتَ ‏ ‏فِيهِ ‏ ‏نُكْتَةٌ ‏ ‏بَيْضَاءُ حَتَّى تَصِيرَ عَلَى قَلْبَيْنِ عَلَى أَبْيَضَ مِثْلِ ‏ ‏الصَّفَا ‏ ‏فَلَا تَضُرُّهُ فِتْنَةٌ مَا دَامَتْ السَّمَاوَاتُ وَالْأَرْضُ وَالْآخَرُ أَسْوَدُ ‏ ‏مُرْبَادًّا ‏ ‏كَالْكُوزِ ‏ ‏مُجَخِّيًا ‏ ‏لَا يَعْرِفُ مَعْرُوفًا وَلَا يُنْكِرُ مُنْكَرًا إِلَّا مَا ‏ ‏أُشْرِبَ ‏ ‏مِنْ هَوَاهُ ‏ ‏قَالَ ‏ ‏حُذَيْفَةُ ‏ ‏وَحَدَّثْتُهُ ‏ ‏أَنَّ بَيْنَكَ وَبَيْنَهَا بَابًا مُغْلَقًا يُوشِكُ أَنْ يُكْسَرَ قَالَ ‏ ‏عُمَرُ ‏ ‏أَكَسْرًا لَا أَبَا لَكَ فَلَوْ أَنَّهُ فُتِحَ لَعَلَّهُ كَانَ يُعَادُ قُلْتُ لَا بَلْ يُكْسَرُ وَحَدَّثْتُهُ أَنَّ ذَلِكَ الْبَابَ رَجُلٌ يُقْتَلُ أَوْ يَمُوتُ حَدِيثًا لَيْسَ بِالْأَغَالِيطِ ‏ ‏قَالَ ‏ ‏أَبُو خَالِدٍ ‏ ‏فَقُلْتُ ‏ ‏لِسَعْدٍ ‏ ‏يَا ‏ ‏أَبَا مَالِكٍ ‏ ‏مَا أَسْوَدُ ‏ ‏مُرْبَادًّا ‏ ‏قَالَ شِدَّةُ الْبَيَاضِ فِي سَوَادٍ قَالَ قُلْتُ فَمَا الْكُوزُ ‏ ‏مُجَخِّيًا ‏ ‏قَالَ مَنْكُوسًا ‏ ‏و حَدَّثَنِي ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ الْفَزَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ ‏ ‏حُذَيْفَةُ ‏ ‏مِنْ عِنْدِ ‏ ‏عُمَرَ ‏ ‏جَلَسَ فَحَدَّثَنَا فَقَالَ إِنَّ أَمِيرَ الْمُؤْمِنِينَ أَمْسِ لَمَّا جَلَسْتُ إِلَيْهِ سَأَلَ أَصْحَابَهُ أَيُّكُمْ يَحْفَظُ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْفِتَنِ وَسَاقَ الْحَدِيثَ بِمِثْلِ حَدِيثِ ‏ ‏أَبِي خَالِدٍ ‏ ‏وَلَمْ يَذْكُرْ تَفْسِيرَ ‏ ‏أَبِي مَالِكٍ ‏ ‏لِقَوْلِهِ مُرْبَادًّا مُجَخِّيًا ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏وَعَمْرُو بْنُ عَلِيٍّ ‏ ‏وَعُقْبَةُ بْنُ مُكْرَمٍ الْعَمِّيُّ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏قَالَ مَنْ يُحَدِّثُنَا أَوْ قَالَ أَيُّكُمْ يُحَدِّثُنَا وَفِيهِمْ ‏ ‏حُذَيْفَةُ ‏ ‏مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْفِتْنَةِ قَالَ ‏ ‏حُذَيْفَةُ ‏ ‏أَنَا وَسَاقَ الْحَدِيثَ كَنَحْوِ حَدِيثِ ‏ ‏أَبِي مَالِكٍ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏وَقَالَ فِي الْحَدِيثِ قَالَ ‏ ‏حُذَيْفَةُ ‏ ‏حَدَّثْتُهُ حَدِيثًا لَيْسَ بِالْأَغَالِيطِ وَقَالَ ‏ ‏يَعْنِي أَنَّهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('51cccf81-2367-5b73-82ca-096b2359e215', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '208', '‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏وَابْنُ أَبِي عُمَرَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏مَرْوَانَ الْفَزَارِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَدَأَ الْإِسْلَامُ ‏ ‏غَرِيبًا ‏ ‏وَسَيَعُودُ كَمَا بَدَأَ غَرِيبًا ‏ ‏فَطُوبَى ‏ ‏لِلْغُرَبَاءِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('43b1e27f-cafb-5e45-b3de-922d071c0341', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '209', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏وَالْفَضْلُ بْنُ سَهْلٍ الْأَعْرَجُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَبَابَةُ بْنُ سَوَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ وَهُوَ ابْنُ مُحَمَّدٍ الْعُمَرِيُّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْإِسْلَامَ بَدَأَ غَرِيبًا وَسَيَعُودُ غَرِيبًا كَمَا بَدَأَ وَهُوَ ‏ ‏يَأْرِزُ ‏ ‏بَيْنَ الْمَسْجِدَيْنِ كَمَا تَأْرِزُ الْحَيَّةُ فِي جُحْرِهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('512c0746-6f0e-53c0-8de8-ef3aab0de230', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '210', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ نُمَيْرٍ ‏ ‏وَأَبُو أُسَامَةَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْإِيمَانَ ‏ ‏لَيَأْرِزُ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَمَا ‏ ‏تَأْرِزُ ‏ ‏الْحَيَّةُ إِلَى جُحْرِهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2d380bf9-1d43-50c1-a9ae-fb4ac1b5b1ec', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '211', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى لَا يُقَالَ فِي الْأَرْضِ اللَّهُ اللَّهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('da524b58-3624-58bd-83e1-4bdeb21cddd0', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '212', '‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ عَلَى أَحَدٍ يَقُولُ اللَّهُ اللَّهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('133112ec-2552-5904-a96f-99ee75166804', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '213', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ نُمَيْرٍ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ ‏ ‏لِأَبِي كُرَيْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏حُذَيْفَةَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَحْصُوا ‏ ‏لِي كَمْ يَلْفِظُ الْإِسْلَامَ قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ أَتَخَافُ عَلَيْنَا وَنَحْنُ مَا بَيْنَ السِّتِّ مِائَةٍ إِلَى السَّبْعِ مِائَةٍ قَالَ إِنَّكُمْ لَا تَدْرُونَ لَعَلَّكُمْ أَنْ ‏ ‏تُبْتَلَوْا ‏ ‏قَالَ ‏ ‏فَابْتُلِيَنَا ‏ ‏حَتَّى جَعَلَ الرَّجُلُ مِنَّا لَا ‏ ‏يُصَلِّي إِلَّا سِرًّا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8eeaf669-73b6-52a1-89cf-509d7e570f78', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '214', '‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَسْمًا فَقُلْتُ يَا رَسُولَ اللَّهِ أَعْطِ فُلَانًا فَإِنَّهُ مُؤْمِنٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مُسْلِمٌ أَقُولُهَا ثَلَاثًا وَيُرَدِّدُهَا عَلَيَّ ثَلَاثًا أَوْ مُسْلِمٌ ثُمَّ قَالَ ‏ ‏إِنِّي لَأُعْطِي الرَّجُلَ وَغَيْرُهُ أَحَبُّ إِلَيَّ مِنْهُ مَخَافَةَ أَنْ ‏ ‏يَكُبَّهُ ‏ ‏اللَّهُ فِي النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('80377cda-94a0-5731-a1f8-0290e2829ef5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '215', '‏ ‏حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَامِرُ بْنُ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْطَى ‏ ‏رَهْطًا ‏ ‏وَسَعْدٌ ‏ ‏جَالِسٌ فِيهِمْ قَالَ ‏ ‏سَعْدٌ ‏ ‏فَتَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمْ مَنْ لَمْ يُعْطِهِ وَهُوَ أَعْجَبُهُمْ إِلَيَّ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ عَنْ فُلَانٍ فَوَاللَّهِ إِنِّي لَأَرَاهُ مُؤْمِنًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مُسْلِمًا قَالَ فَسَكَتُّ قَلِيلًا ثُمَّ غَلَبَنِي مَا أَعْلَمُ مِنْهُ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ عَنْ فُلَانٍ فَوَاللَّهِ إِنِّي لَأَرَاهُ مُؤْمِنًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مُسْلِمًا قَالَ فَسَكَتُّ قَلِيلًا ثُمَّ غَلَبَنِي مَا عَلِمْتُ مِنْهُ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا لَكَ عَنْ فُلَانٍ فَوَاللَّهِ إِنِّي لَأَرَاهُ مُؤْمِنًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مُسْلِمًا ‏ ‏إِنِّي لَأُعْطِي الرَّجُلَ وَغَيْرُهُ أَحَبُّ إِلَيَّ مِنْهُ خَشْيَةَ أَنْ ‏ ‏يُكَبَّ ‏ ‏فِي النَّارِ عَلَى وَجْهِهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ عَلِيٍّ الْحُلْوَانِيُّ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَعْقُوبُ وَهُوَ ابْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَامِرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَعْدٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَعْطَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَهْطًا ‏ ‏وَأَنَا جَالِسٌ فِيهِمْ بِمِثْلِ حَدِيثِ ‏ ‏ابْنِ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ عَمِّهِ وَزَادَ فَقُمْتُ إِلَى رَسُولِ اللَّهِ فَسَارَرْتُهُ فَقُلْتُ مَا لَكَ عَنْ فُلَانٍ ‏ ‏و حَدَّثَنَا ‏ ‏الْحَسَنُ الْحُلْوَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏عَنْ ‏ ‏إِسْمَعِيلَ بْنِ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ هَذَا ‏ ‏فَقَالَ فِي حَدِيثِهِ فَضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ بَيْنَ عُنُقِي وَكَتِفِي ثُمَّ قَالَ أَقِتَالًا أَيْ ‏ ‏سَعْدُ ‏ ‏إِنِّي لَأُعْطِي الرَّجُلَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('000f69e9-be58-5db2-ab59-e435b248055c', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '216', '‏ ‏و حَدَّثَنِي ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏وَسَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَحْنُ أَحَقُّ بِالشَّكِّ مِنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ قَالَ ‏ { ‏رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى قَالَ ‏ ‏أَوَ لَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي ‏} ‏قَالَ وَيَرْحَمُ اللَّهُ ‏ ‏لُوطًا ‏ ‏لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ وَلَوْ لَبِثْتُ فِي السِّجْنِ طُولَ لَبْثِ ‏ ‏يُوسُفَ ‏ ‏لَأَجَبْتُ الدَّاعِيَ ‏ ‏و حَدَّثَنِي ‏ ‏بِهِ إِنْ شَاءَ اللَّهُ ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ أَسْمَاءَ الضُّبَعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جُوَيْرِيَةُ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏وَأَبَا عُبَيْدٍ ‏ ‏أَخْبَرَاهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ حَدِيثِ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏وَفِي حَدِيثِ ‏ ‏مَالِكٍ ‏ { ‏وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي ‏} ‏قَالَ ثُمَّ قَرَأَ هَذِهِ الْآيَةَ حَتَّى ‏ ‏جَازَهَا ‏ ‏حَدَّثَنَاه ‏ ‏عَبْدُ بْنُ حُمَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَعْقُوبُ يَعْنِي ابْنَ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُوَيْسٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏كَرِوَايَةِ ‏ ‏مَالِكٍ ‏ ‏بِإِسْنَادِهِ وَقَالَ ثُمَّ قَرَأَ هَذِهِ الْآيَةَ حَتَّى ‏ ‏أَنْجَزَهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('31d28764-1728-59bd-ae29-d497e0aa46f1', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '217', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ الْأَنْبِيَاءِ مِنْ نَبِيٍّ إِلَّا قَدْ أُعْطِيَ مِنْ الْآيَاتِ مَا مِثْلُهُ آمَنَ عَلَيْهِ الْبَشَرُ وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَى اللَّهُ إِلَيَّ فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('58379a25-4c01-5645-829f-a20d7d735ad8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '218', '‏ ‏حَدَّثَنِي ‏ ‏يُونُسُ بْنُ عَبْدِ الْأَعْلَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ وَأَخْبَرَنِي ‏ ‏عَمْرٌو ‏ ‏أَنَّ ‏ ‏أَبَا يُونُسَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَا يَسْمَعُ بِي أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ يَهُودِيٌّ وَلَا نَصْرَانِيٌّ ثُمَّ يَمُوتُ وَلَمْ يُؤْمِنْ بِالَّذِي أُرْسِلْتُ بِهِ إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('812d2964-994f-5e8f-adeb-213bac0ef27d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '219', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ صَالِحٍ الْهَمْدَانِيِّ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَجُلًا مِنْ أَهْلِ ‏ ‏خُرَاسَانَ ‏ ‏سَأَلَ ‏ ‏الشَّعْبِيَّ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏إِنَّ مَنْ قِبَلَنَا مِنْ أَهْلِ ‏ ‏خُرَاسَانَ ‏ ‏يَقُولُونَ فِي الرَّجُلِ إِذَا أَعْتَقَ أَمَتَهُ ثُمَّ تَزَوَّجَهَا فَهُوَ كَالرَّاكِبِ ‏ ‏بَدَنَتَهُ ‏ ‏فَقَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بُرْدَةَ بْنُ أَبِي مُوسَى ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثَةٌ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ رَجُلٌ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏آمَنَ بِنَبِيِّهِ وَأَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَآمَنَ بِهِ وَاتَّبَعَهُ وَصَدَّقَهُ فَلَهُ أَجْرَانِ وَعَبْدٌ مَمْلُوكٌ أَدَّى حَقَّ اللَّهِ تَعَالَى وَحَقَّ سَيِّدِهِ فَلَهُ أَجْرَانِ وَرَجُلٌ كَانَتْ لَهُ أَمَةٌ فَغَذَّاهَا فَأَحْسَنَ غِذَاءَهَا ثُمَّ أَدَّبَهَا فَأَحْسَنَ أَدَبَهَا ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا فَلَهُ أَجْرَانِ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏الشَّعْبِيُّ ‏ ‏لِلْخُرَاسَانِيِّ ‏ ‏خُذْ هَذَا الْحَدِيثَ بِغَيْرِ شَيْءٍ فَقَدْ كَانَ الرَّجُلُ يَرْحَلُ فِيمَا دُونَ هَذَا إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ بْنُ سُلَيْمَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏ابْنُ أَبِي عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ صَالِحٍ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('9a2ce602-887f-57d1-bbe6-cd2932157cf3', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '220', '‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رُمْحٍ ‏ ‏أَخْبَرَنَا ‏ ‏اللَّيْثُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏ابْنِ الْمُسَيَّبِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏لَيُوشِكَنَّ أَنْ يَنْزِلَ فِيكُمْ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَكَمًا ‏ ‏مُقْسِطًا ‏ ‏فَيَكْسِرَ الصَّلِيبَ وَيَقْتُلَ الْخِنْزِيرَ وَيَضَعَ ‏ ‏الْجِزْيَةَ ‏ ‏وَيَفِيضُ ‏ ‏الْمَالُ حَتَّى لَا يَقْبَلَهُ أَحَدٌ ‏ ‏و حَدَّثَنَاه ‏ ‏عَبْدُ الْأَعْلَى بْنُ حَمَّادٍ ‏ ‏وَأَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏ح ‏ ‏و حَدَّثَنِيهِ ‏ ‏حَرْمَلَةُ بْنُ يَحْيَى ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏حَسَنٌ الْحُلْوَانِيُّ ‏ ‏وَعَبْدُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏كُلُّهُمْ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏وَفِي رِوَايَةِ ‏ ‏ابْنِ عُيَيْنَةَ ‏ ‏إِمَامًا ‏ ‏مُقْسِطًا ‏ ‏وَحَكَمًا عَدْلًا ‏ ‏وَفِي رِوَايَةِ ‏ ‏يُونُسَ ‏ ‏حَكَمًا عَادِلًا وَلَمْ يَذْكُرْ إِمَامًا ‏ ‏مُقْسِطًا ‏ ‏وَفِي حَدِيثِ ‏ ‏صَالِحٍ ‏ ‏حَكَمًا ‏ ‏مُقْسِطًا ‏ ‏كَمَا قَالَ ‏ ‏اللَّيْثُ ‏ ‏وَفِي حَدِيثِهِ مِنْ الزِّيَادَةِ وَحَتَّى تَكُونَ السَّجْدَةُ الْوَاحِدَةُ خَيْرًا مِنْ الدُّنْيَا وَمَا فِيهَا ‏ ‏ثُمَّ ‏ ‏يَقُولُا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏اقْرَءُوا إِنْ شِئْتُمْ ‏ { ‏وَإِنْ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏إِلَّا لَيُؤْمِنَنَّ بِهِ قَبْلَ مَوْتِهِ ‏} ‏الْآيَةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
