insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ac57315f-a035-515b-a767-d76424ae26d8', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '223', '‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَخِي ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏مَوْلَى ‏ ‏أَبِي قَتَادَةَ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ أَنْتُمْ إِذَا نَزَلَ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏فِيكُمْ وَأَمَّكُمْ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('389bcdc5-d642-5e31-91c3-1392165c46f6', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '224', '‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏أَبِي قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَيْفَ أَنْتُمْ إِذَا نَزَلَ فِيكُمْ ‏ ‏ابْنُ مَرْيَمَ ‏ ‏فَأَمَّكُمْ مِنْكُمْ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ أَبِي ذِئْبٍ ‏ ‏إِنَّ ‏ ‏الْأَوْزَاعِيَّ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَإِمَامُكُمْ مِنْكُمْ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏تَدْرِي مَا أَمَّكُمْ مِنْكُمْ قُلْتُ تُخْبِرُنِي قَالَ فَأَمَّكُمْ بِكِتَابِ رَبِّكُمْ تَبَارَكَ وَتَعَالَى وَسُنَّةِ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('ff285273-161b-5579-b419-5b2e7b56907d', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '225', '‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ شُجَاعٍ ‏ ‏وَهَارُونُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَحَجَّاجُ بْنُ الشَّاعِرِ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏حَجَّاجٌ وَهُوَ ابْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُا ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الْحَقِّ ‏ ‏ظَاهِرِينَ ‏ ‏إِلَى يَوْمِ الْقِيَامَةِ قَالَ فَيَنْزِلُ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَقُولُ أَمِيرُهُمْ تَعَالَ صَلِّ لَنَا فَيَقُولُ لَا إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ أُمَرَاءُ ‏ ‏تَكْرِمَةَ اللَّهِ هَذِهِ الْأُمَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('256541f5-b4c1-56b0-ae51-20d4d699d177', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '226', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏وَعَلِيُّ بْنُ حُجْرٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏إِسْمَعِيلُ يَعْنُونَ ابْنَ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏الْعَلَاءِ وَهُوَ ابْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا فَإِذَا طَلَعَتْ مِنْ مَغْرِبِهَا آمَنَ النَّاسُ كُلُّهُمْ أَجْمَعُونَ فَيَوْمَئِذٍ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏} ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏ح ‏ ‏و حَدَّثَنِي ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏كِلَاهُمَا ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ الْقَعْقَاعِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏هَمَّامِ بْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِ ‏ ‏حَدِيثِ ‏ ‏لْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('8e249a74-e559-5ff0-84dd-8d0e5276a0e5', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '227', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَزُهَيْرُ بْنُ حَرْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏ح ‏ ‏و حَدَّثَنِيهِ ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ غَزْوَانَ ‏ ‏ح ‏ ‏و حَدَّثَنَا ‏ ‏أَبُو كُرَيْبٍ مُحَمَّدُ بْنُ الْعَلَاءِ ‏ ‏وَاللَّفْظُ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ إِذَا خَرَجْنَ لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا طُلُوعُ الشَّمْسِ مِنْ مَغْرِبِهَا ‏ ‏وَالدَّجَّالُ ‏ ‏وَدَابَّةُ الْأَرْضِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('89403cda-aa7e-578b-a3ca-b22992c8ed37', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '228', '‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏ابْنِ عُلَيَّةَ ‏ ‏قَالَ ‏ ‏ابْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ يَزِيدَ التَّيْمِيِّ ‏ ‏سَمِعَهُ ‏ ‏فِيمَا أَعْلَمُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمًا ‏ ‏أَتَدْرُونَ أَيْنَ تَذْهَبُ هَذِهِ الشَّمْسُ قَالُوا اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ إِنَّ هَذِهِ ‏ ‏تَجْرِي حَتَّى تَنْتَهِيَ إِلَى مُسْتَقَرِّهَا تَحْتَ الْعَرْشِ فَتَخِرُّ سَاجِدَةً فَلَا تَزَالُ كَذَلِكَ حَتَّى يُقَالَ لَهَا ارْتَفِعِي ارْجِعِي مِنْ حَيْثُ جِئْتِ فَتَرْجِعُ فَتُصْبِحُ طَالِعَةً مِنْ مَطْلِعِهَا ثُمَّ ‏ ‏تَجْرِي حَتَّى تَنْتَهِيَ إِلَى مُسْتَقَرِّهَا تَحْتَ الْعَرْشِ فَتَخِرُّ سَاجِدَةً وَلَا تَزَالُ كَذَلِكَ حَتَّى يُقَالَ لَهَا ارْتَفِعِي ارْجِعِي مِنْ حَيْثُ جِئْتِ فَتَرْجِعُ فَتُصْبِحُ طَالِعَةً مِنْ مَطْلِعِهَا ثُمَّ ‏ ‏تَجْرِي لَا يَسْتَنْكِرُ النَّاسَ مِنْهَا شَيْئًا حَتَّى تَنْتَهِيَ إِلَى مُسْتَقَرِّهَا ذَاكَ تَحْتَ الْعَرْشِ فَيُقَالُ لَهَا ارْتَفِعِي أَصْبِحِي طَالِعَةً مِنْ مَغْرِبِكِ فَتُصْبِحُ طَالِعَةً مِنْ مَغْرِبِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَدْرُونَ مَتَى ‏ ‏ذَاكُمْ ذَاكَ حِينَ ‏ { ‏لَا يَنْفَعُ نَفْسًا إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْرًا ‏} ‏و حَدَّثَنِي ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَيَانٍ الْوَاسِطِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمًا ‏ ‏أَتَدْرُونَ أَيْنَ تَذْهَبُ هَذِهِ الشَّمْسُ بِمِثْلِ مَعْنَى حَدِيثِ ‏ ‏ابْنِ عُلَيَّةَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('383ac720-0f3c-5640-8ccf-1331dbbcc941', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '229', '‏ ‏و حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏وَأَبُو كُرَيْبٍ ‏ ‏وَاللَّفْظُ ‏ ‏لَأَبِي كُرَيْبٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ الْمَسْجِدَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسٌ فَلَمَّا غَابَتْ الشَّمْسُ قَالَ يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏هَلْ تَدْرِي أَيْنَ تَذْهَبُ هَذِهِ قَالَ قُلْتُ اللَّهُ وَرَسُولُهُ أَعْلَمُ قَالَ ‏ ‏فَإِنَّهَا تَذْهَبُ فَتَسْتَأْذِنُ فِي السُّجُودِ فَيُؤْذَنُ لَهَا وَكَأَنَّهَا قَدْ قِيلَ لَهَا ارْجِعِي مِنْ حَيْثُ جِئْتِ فَتَطْلُعُ مِنْ مَغْرِبِهَا قَالَ ثُمَّ قَرَأَ فِي قِرَاءَةِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَذَلِكَ مُسْتَقَرٌّ لَهَا ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('266b003b-c788-532a-bdd5-233c09ad68dd', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '230', '‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ الْأَشَجُّ ‏ ‏وَإِسْحَقُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏إِسْحَقُ ‏ ‏أَخْبَرَنَا ‏ ‏وَقَالَ ‏ ‏الْأَشَجُّ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَوْلِ اللَّهِ تَعَالَى ‏ { ‏وَالشَّمْسُ ‏ ‏تَجْرِي لِمُسْتَقَرٍّ لَهَا ‏} ‏قَالَ ‏ ‏مُسْتَقَرُّهَا تَحْتَ الْعَرْشِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('a360b854-d48d-5058-a614-8e6de75457af', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '231', '‏ ‏حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ أَحْمَدُ بْنُ عَمْرِو بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ سَرْحٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ زَوْجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّهَا قَالَتْ كَانَ ‏ ‏أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْوَحْيِ الرُّؤْيَا الصَّادِقَةَ فِي النَّوْمِ فَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ فَلَقِ الصُّبْحِ ثُمَّ حُبِّبَ إِلَيْهِ الْخَلَاءُ فَكَانَ يَخْلُو ‏ ‏بِغَارِ حِرَاءٍ ‏ ‏يَتَحَنَّثُ فِيهِ ‏ ‏وَهُوَ التَّعَبُّدُ ‏ ‏اللَّيَالِيَ أُوْلَاتِ الْعَدَدِ ‏ ‏قَبْلَ أَنْ يَرْجِعَ إِلَى أَهْلِهِ وَيَتَزَوَّدُ لِذَلِكَ ثُمَّ يَرْجِعُ إِلَى ‏ ‏خَدِيجَةَ ‏ ‏فَيَتَزَوَّدُ لِمِثْلِهَا حَتَّى فَجِئَهُ الْحَقُّ وَهُوَ فِي ‏ ‏غَارِ حِرَاءٍ ‏ ‏فَجَاءَهُ الْمَلَكُ فَقَالَ اقْرَأْ قَالَ مَا أَنَا بِقَارِئٍ قَالَ فَأَخَذَنِي فَغَطَّنِي حَتَّى بَلَغَ مِنِّي ‏ ‏الْجَهْدَ ‏ ‏ثُمَّ أَرْسَلَنِي فَقَالَ اقْرَأْ قَالَ قُلْتُ مَا أَنَا بِقَارِئٍ قَالَ فَأَخَذَنِي فَغَطَّنِي الثَّانِيَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ ثُمَّ أَرْسَلَنِي فَقَالَ أَقْرَأْ فَقُلْتُ مَا أَنَا بِقَارِئٍ فَأَخَذَنِي فَغَطَّنِي الثَّالِثَةَ حَتَّى بَلَغَ مِنِّي الْجَهْدَ ثُمَّ أَرْسَلَنِي فَقَالَ ‏ { ‏اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ اقْرَأْ وَرَبُّكَ الْأَكْرَمُ الَّذِي عَلَّمَ بِالْقَلَمِ عَلَّمَ الْإِنْسَانَ مَا لَمْ يَعْلَمْ ‏} ‏فَرَجَعَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرْجُفُ ‏ ‏بَوَادِرُهُ ‏ ‏حَتَّى دَخَلَ عَلَى ‏ ‏خَدِيجَةَ ‏ ‏فَقَالَ زَمِّلُونِي زَمِّلُونِي فَزَمَّلُوهُ حَتَّى ذَهَبَ عَنْهُ الرَّوْعُ ثُمَّ قَالَ ‏ ‏لِخَدِيجَةَ ‏ ‏أَيْ ‏ ‏خَدِيجَةُ ‏ ‏مَا لِي وَأَخْبَرَهَا الْخَبَرَ قَالَ لَقَدْ خَشِيتُ عَلَى نَفْسِي قَالَتْ لَهُ ‏ ‏خَدِيجَةُ ‏ ‏كَلَّا أَبْشِرْ فَوَاللَّهِ لَا يُخْزِيكَ اللَّهُ أَبَدًا وَاللَّهِ إِنَّكَ ‏ ‏لَتَصِلُ ‏ ‏الرَّحِمَ ‏ ‏وَتَصْدُقُ الْحَدِيثَ وَتَحْمِلُ الْكَلَّ وَتَكْسِبُ الْمَعْدُومَ وَتَقْرِي الضَّيْفَ وَتُعِينُ عَلَى نَوَائِبِ الْحَقِّ فَانْطَلَقَتْ بِهِ ‏ ‏خَدِيجَةُ ‏ ‏حَتَّى أَتَتْ بِهِ ‏ ‏وَرَقَةَ بْنَ نَوْفَلِ بْنِ أَسَدِ بْنِ عَبْدِ الْعُزَّى ‏ ‏وَهُوَ ابْنُ عَمِّ ‏ ‏خَدِيجَةَ ‏ ‏أَخِي أَبِيهَا وَكَانَ امْرَأً تَنَصَّرَ فِي الْجَاهِلِيَّةِ وَكَانَ يَكْتُبُ الْكِتَابَ الْعَرَبِيَّ وَيَكْتُبُ مِنْ الْإِنْجِيلِ بِالْعَرَبِيَّةِ مَا شَاءَ اللَّهُ أَنْ يَكْتُبَ وَكَانَ شَيْخًا كَبِيرًا قَدْ عَمِيَ فَقَالَتْ لَهُ ‏ ‏خَدِيجَةُ ‏ ‏أَيْ عَمِّ اسْمَعْ مِنْ ابْنِ أَخِيكَ قَالَ ‏ ‏وَرَقَةُ بْنُ نَوْفَلٍ ‏ ‏يَا ‏ ‏ابْنَ أَخِي مَاذَا ‏ ‏تَرَى فَأَخْبَرَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَبَرَ مَا رَآهُ فَقَالَ لَهُ ‏ ‏وَرَقَةُ ‏ ‏هَذَا النَّامُوسُ الَّذِي أُنْزِلَ عَلَى ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا لَيْتَنِي فِيهَا ‏ ‏جَذَعًا ‏ ‏يَا لَيْتَنِي أَكُونُ حَيًّا حِينَ يُخْرِجُكَ قَوْمُكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَ مُخْرِجِيَّ هُمْ قَالَ ‏ ‏وَرَقَةُ ‏ ‏نَعَمْ لَمْ يَأْتِ رَجُلٌ قَطُّ بِمَا جِئْتَ بِهِ إِلَّا عُودِيَ وَإِنْ يُدْرِكْنِي يَوْمُكَ أَنْصُرْكَ نَصْرًا مُؤَزَّرًا ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَأَخْبَرَنِي ‏ ‏عُرْوَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْوَحْيِ وَسَاقَ الْحَدِيثَ بِمِثْلِ حَدِيثِ ‏ ‏يُونُسَ ‏ ‏غَيْرَ أَنَّهُ قَالَ فَوَاللَّهِ لَا يُحْزِنُكَ اللَّهُ أَبَدًا وَقَالَ قَالَتْ ‏ ‏خَدِيجَةُ ‏ ‏أَيْ ابْنَ عَمِّ اسْمَعْ مِنْ ابْنِ أَخِيكَ ‏ ‏و حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ شُعَيْبِ بْنِ اللَّيْثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يَقُولُ قَالَتْ ‏ ‏عَائِشَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَجَعَ إِلَى ‏ ‏خَدِيجَةَ ‏ ‏يَرْجُفُ فُؤَادُهُ وَاقْتَصَّ الْحَدِيثَ بِمِثْلِ حَدِيثِ ‏ ‏يُونُسَ ‏ ‏وَمَعْمَرٍ ‏ ‏وَلَمْ يَذْكُرْ أَوَّلَ حَدِيثِهِمَا مِنْ قَوْلِهِ أَوَّلُ مَا بُدِئَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْوَحْيِ الرُّؤْيَا الصَّادِقَةُ وَتَابَعَ ‏ ‏يُونُسَ ‏ ‏عَلَى قَوْلِهِ فَوَاللَّهِ لَا ‏ ‏يَخْزِيكَ اللَّهُ أَبَدًا وَذَكَرَ قَوْلَ ‏ ‏خَدِيجَةَ ‏ ‏أَيْ ابْنَ عَمِّ اسْمَعْ مِنْ ابْنِ أَخِيكَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('85edebf8-9cf6-5f02-a2da-4e2d05248e3e', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '232', '‏ ‏و حَدَّثَنِي ‏ ‏أَبُو الطَّاهِرِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يُونُسُ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ الْأَنْصَارِيَّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُحَدِّثُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُحَدِّثُ عَنْ ‏ ‏فَتْرَةِ ‏ ‏الْوَحْيِ قَالَ فِي حَدِيثِهِ ‏ ‏فَبَيْنَا أَنَا أَمْشِي سَمِعْتُ صَوْتًا مِنْ السَّمَاءِ فَرَفَعْتُ رَأْسِي فَإِذَا ‏ ‏الْمَلَكُ ‏ ‏الَّذِي جَاءَنِي ‏ ‏بِحِرَاءٍ ‏ ‏جَالِسًا عَلَى كُرْسِيٍّ بَيْنَ السَّمَاءِ وَالْأَرْضِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجُئِثْتُ ‏ ‏مِنْهُ ‏ ‏فَرَقًا ‏ ‏فَرَجَعْتُ فَقُلْتُ ‏ ‏زَمِّلُونِي ‏ ‏زَمِّلُونِي ‏ ‏فَدَثَّرُونِي ‏ ‏فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏يَا أَيُّهَا ‏ ‏الْمُدَّثِّرُ ‏ ‏قُمْ فَأَنْذِرْ وَرَبَّكَ فَكَبِّرْ وَثِيَابَكَ فَطَهِّرْ وَالرُّجْزَ فَاهْجُرْ ‏} ‏وَهِيَ الْأَوْثَانُ قَالَ ثُمَّ تَتَابَعَ الْوَحْيُ ‏ ‏و حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ شُعَيْبِ بْنِ اللَّيْثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُقَيْلُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ شِهَابٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يَقُولُ أَخْبَرَنِي ‏ ‏جَابِرُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏ثُمَّ ‏ ‏فَتَرَ ‏ ‏الْوَحْيُ عَنِّي ‏ ‏فَتْرَةً ‏ ‏فَبَيْنَا أَنَا أَمْشِي ثُمَّ ذَكَرَ مِثْلَ حَدِيثِ ‏ ‏يُونُسَ ‏ ‏غَيْرَ أَنَّهُ قَالَ ‏ ‏فَجُئِثْتُ ‏ ‏مِنْهُ فَرَقًا حَتَّى هَوَيْتُ إِلَى الْأَرْضِ ‏ ‏قَالَ ‏ ‏و قَالَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏وَالرُّجْزُ الْأَوْثَانُ قَالَ ثُمَّ حَمِيَ الْوَحْيُ بَعْدُ وَتَتَابَعَ ‏ ‏و حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ رَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏بِهَذَا الْإِسْنَادِ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏يُونُسَ ‏ ‏وَقَالَ فَأَنْزَلَ اللَّهُ تَبَارَكَ وَتَعَالَى ‏ { ‏يَا أَيُّهَا الْمُدَّثِّرُ ‏ ‏إِلَى قَوْلِهِ ‏ ‏وَالرُّجْزَ فَاهْجُرْ ‏} ‏قَبْلَ أَنْ تُفْرَضَ الصَّلَاةُ وَهِيَ الْأَوْثَانُ وَقَالَ فَجُئِثْتُ مِنْهُ كَمَا قَالَ ‏ ‏عُقَيْلٌ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('36416f67-8a16-56e3-b715-526f667b5fe7', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '233', '‏ ‏و حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏يَحْيَى ‏ ‏يَقُولُ سَأَلْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏أَيُّ الْقُرْآنِ أُنْزِلَ قَبْلُ قَالَ ‏ { ‏يَا أَيُّهَا الْمُدَّثِّرُ ‏} ‏فَقُلْتُ أَوْ اقْرَأْ فَقَالَ سَأَلْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏أَيُّ الْقُرْآنِ أُنْزِلَ قَبْلُ قَالَ ‏ { ‏يَا أَيُّهَا الْمُدَّثِّرُ ‏} ‏فَقُلْتُ أَوْ اقْرَأْ قَالَ ‏ ‏جَابِرٌ ‏ ‏أُحَدِّثُكُمْ مَا حَدَّثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَاوَرْتُ ‏ ‏بِحِرَاءٍ ‏ ‏شَهْرًا فَلَمَّا قَضَيْتُ ‏ ‏جِوَارِي ‏ ‏نَزَلْتُ ‏ ‏فَاسْتَبْطَنْتُ ‏ ‏بَطْنَ الْوَادِي فَنُودِيتُ فَنَظَرْتُ أَمَامِي وَخَلْفِي وَعَنْ يَمِينِي وَعَنْ شِمَالِي فَلَمْ أَرَ أَحَدًا ثُمَّ نُودِيتُ فَنَظَرْتُ فَلَمْ أَرَ أَحَدًا ثُمَّ نُودِيتُ فَرَفَعْتُ رَأْسِي فَإِذَا هُوَ عَلَى الْعَرْشِ فِي الْهَوَاءِ ‏ ‏يَعْنِي ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَأَخَذَتْنِي رَجْفَةٌ شَدِيدَةٌ فَأَتَيْتُ ‏ ‏خَدِيجَةَ ‏ ‏فَقُلْتُ ‏ ‏دَثِّرُونِي ‏ ‏فَدَثَّرُونِي فَصَبُّوا عَلَيَّ مَاءً فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا الْمُدَّثِّرُ قُمْ فَأَنْذِرْ وَرَبَّكَ فَكَبِّرْ وَثِيَابَكَ فَطَهِّرْ ‏} ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏بِهَذَا الْإِسْنَادِ وَقَالَ ‏ ‏فَإِذَا هُوَ جَالِسٌ عَلَى عَرْشٍ بَيْنَ السَّمَاءِ وَالْأَرْضِ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('2122ebff-c4f5-51c9-90cf-c1630e7e1e35', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '234', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُتِيتُ بِالْبُرَاقِ وَهُوَ دَابَّةٌ أَبْيَضُ طَوِيلٌ فَوْقَ الْحِمَارِ وَدُونَ الْبَغْلِ يَضَعُ حَافِرَهُ عِنْدَ مُنْتَهَى طَرْفِهِ قَالَ فَرَكِبْتُهُ حَتَّى أَتَيْتُ ‏ ‏بَيْتَ الْمَقْدِسِ ‏ ‏قَالَ فَرَبَطْتُهُ بِالْحَلْقَةِ الَّتِي يَرْبِطُ بِهِ الْأَنْبِيَاءُ قَالَ ثُمَّ دَخَلْتُ الْمَسْجِدَ فَصَلَّيْتُ فِيهِ رَكْعَتَيْنِ ثُمَّ خَرَجْتُ فَجَاءَنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏بِإِنَاءٍ مِنْ خَمْرٍ وَإِنَاءٍ مِنْ لَبَنٍ فَاخْتَرْتُ اللَّبَنَ فَقَالَ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَرْتَ الْفِطْرَةَ ثُمَّ ‏ ‏عَرَجَ ‏ ‏بِنَا إِلَى السَّمَاءِ فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏فَقِيلَ مَنْ أَنْتَ قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ فَفُتِحَ لَنَا فَإِذَا أَنَا ‏ ‏بِآدَمَ ‏ ‏فَرَحَّبَ بِي وَدَعَا لِي بِخَيْرٍ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الثَّانِيَةِ فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقِيلَ مَنْ أَنْتَ قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ فَفُتِحَ لَنَا فَإِذَا أَنَا بِابْنَيْ الْخَالَةِ ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏وَيَحْيَى بْنِ زَكَرِيَّاءَ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِمَا فَرَحَّبَا وَدَعَوَا لِي بِخَيْرٍ ثُمَّ عَرَجَ بِي إِلَى السَّمَاءِ الثَّالِثَةِ فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏فَقِيلَ مَنْ أَنْتَ قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ فَفُتِحَ لَنَا فَإِذَا أَنَا ‏ ‏بِيُوسُفَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا هُوَ قَدْ أُعْطِيَ ‏ ‏شَطْرَ ‏ ‏الْحُسْنِ فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الرَّابِعَةِ فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قِيلَ مَنْ هَذَا قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قَالَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ فَفُتِحَ لَنَا فَإِذَا أَنَا ‏ ‏بِإِدْرِيسَ ‏ ‏فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَرَفَعْنَاهُ مَكَانًا عَلِيًّا ‏} ‏ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الْخَامِسَةِ فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ مَنْ هَذَا قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ فَفُتِحَ لَنَا فَإِذَا أَنَا ‏ ‏بِهَارُونَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ السَّادِسَةِ فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قِيلَ مَنْ هَذَا قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ فَفُتِحَ لَنَا فَإِذَا أَنَا ‏ ‏بِمُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ ثُمَّ عَرَجَ إِلَى السَّمَاءِ السَّابِعَةِ فَاسْتَفْتَحَ ‏ ‏جِبْرِيلُ ‏ ‏فَقِيلَ مَنْ هَذَا قَالَ ‏ ‏جِبْرِيلُ ‏ ‏قِيلَ وَمَنْ مَعَكَ قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِيلَ وَقَدْ بُعِثَ إِلَيْهِ قَالَ قَدْ بُعِثَ إِلَيْهِ فَفُتِحَ لَنَا فَإِذَا أَنَا ‏ ‏بِإِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُسْنِدًا ظَهْرَهُ إِلَى ‏ ‏الْبَيْتِ الْمَعْمُورِ ‏ ‏وَإِذَا هُوَ يَدْخُلُهُ كُلَّ يَوْمٍ سَبْعُونَ أَلْفَ مَلَكٍ لَا يَعُودُونَ إِلَيْهِ ثُمَّ ذَهَبَ بِي إِلَى السِّدْرَةِ الْمُنْتَهَى وَإِذَا وَرَقُهَا كَآذَانِ الْفِيَلَةِ وَإِذَا ثَمَرُهَا كَالْقِلَالِ قَالَ فَلَمَّا ‏ ‏غَشِيَهَا ‏ ‏مِنْ أَمْرِ اللَّهِ مَا غَشِيَ تَغَيَّرَتْ فَمَا أَحَدٌ مِنْ خَلْقِ اللَّهِ يَسْتَطِيعُ أَنْ ‏ ‏يَنْعَتَهَا ‏ ‏مِنْ حُسْنِهَا فَأَوْحَى اللَّهُ إِلَيَّ مَا أَوْحَى فَفَرَضَ عَلَيَّ خَمْسِينَ صَلَاةً فِي كُلِّ يَوْمٍ وَلَيْلَةٍ فَنَزَلْتُ إِلَى ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا فَرَضَ رَبُّكَ عَلَى أُمَّتِكَ قُلْتُ خَمْسِينَ صَلَاةً قَالَ ارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ فَإِنَّ أُمَّتَكَ لَا يُطِيقُونَ ذَلِكَ فَإِنِّي قَدْ ‏ ‏بَلَوْتُ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏وَخَبَرْتُهُمْ قَالَ فَرَجَعْتُ إِلَى رَبِّي فَقُلْتُ يَا رَبِّ خَفِّفْ عَلَى أُمَّتِي فَحَطَّ عَنِّي خَمْسًا فَرَجَعْتُ إِلَى ‏ ‏مُوسَى ‏ ‏فَقُلْتُ حَطَّ عَنِّي خَمْسًا قَالَ إِنَّ أُمَّتَكَ لَا يُطِيقُونَ ذَلِكَ فَارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ قَالَ فَلَمْ أَزَلْ أَرْجِعُ بَيْنَ رَبِّي تَبَارَكَ وَتَعَالَى وَبَيْنَ ‏ ‏مُوسَى ‏ ‏عَلَيْهِ السَّلَام ‏ ‏حَتَّى قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّهُنَّ خَمْسُ صَلَوَاتٍ كُلَّ يَوْمٍ وَلَيْلَةٍ لِكُلِّ صَلَاةٍ عَشْرٌ فَذَلِكَ خَمْسُونَ صَلَاةً وَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةً فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ عَشْرًا وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا لَمْ تُكْتَبْ شَيْئًا فَإِنْ عَمِلَهَا كُتِبَتْ سَيِّئَةً وَاحِدَةً قَالَ فَنَزَلْتُ حَتَّى انْتَهَيْتُ إِلَى ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرْتُهُ فَقَالَ ارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ قَدْ رَجَعْتُ إِلَى رَبِّي حَتَّى اسْتَحْيَيْتُ مِنْهُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('292805bb-deac-5788-adb6-d2deaa584e5f', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '235', '‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ هَاشِمٍ الْعَبْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيتُ فَانْطَلَقُوا بِي إِلَى ‏ ‏زَمْزَمَ ‏ ‏فَشُرِحَ ‏ ‏عَنْ صَدْرِي ثُمَّ غُسِلَ بِمَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ أُنْزِلْتُ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
insert into public.hadiths (id, book_id, hadith_number, text_ar, ref, published) values ('49e26046-ced7-5b8d-81eb-58e5b48e3771', '153eb269-47c8-4d4a-992c-368cb10c4d8d', '236', '‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ الْبُنَانِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَلْعَبُ مَعَ الْغِلْمَانِ فَأَخَذَهُ ‏ ‏فَصَرَعَهُ ‏ ‏فَشَقَّ عَنْ قَلْبِهِ فَاسْتَخْرَجَ الْقَلْبَ فَاسْتَخْرَجَ مِنْهُ ‏ ‏عَلَقَةً ‏ ‏فَقَالَ هَذَا حَظُّ الشَّيْطَانِ مِنْكَ ثُمَّ غَسَلَهُ فِي طَسْتٍ مِنْ ذَهَبٍ بِمَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ ‏ ‏لَأَمَهُ ‏ ‏ثُمَّ أَعَادَهُ فِي مَكَانِهِ وَجَاءَ الْغِلْمَانُ يَسْعَوْنَ إِلَى أُمِّهِ ‏ ‏يَعْنِي ‏ ‏ظِئْرَهُ ‏ ‏فَقَالُوا إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏قَدْ قُتِلَ فَاسْتَقْبَلُوهُ وَهُوَ ‏ ‏مُنْتَقِعُ ‏ ‏اللَّوْنِ قَالَ ‏ ‏أَنَسٌ ‏ ‏وَقَدْ كُنْتُ أَرْئِي أَثَرَ ذَلِكَ الْمِخْيَطِ فِي صَدْرِهِ ‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ سَعِيدٍ الْأَيْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏سُلَيْمَانُ وَهُوَ ابْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَرِيكُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُنَا عَنْ لَيْلَةَ أُسْرِيَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مَسْجِدِ الْكَعْبَةِ ‏ ‏أَنَّهُ جَاءَهُ ثَلَاثَةُ نَفَرٍ ‏ ‏قَبْلَ أَنْ ‏ ‏يُوحَى إِلَيْهِ ‏ ‏وَهُوَ نَائِمٌ فِي ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏وَسَاقَ الْحَدِيثَ بِقِصَّتِهِ نَحْوَ حَدِيثِ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏وَقَدَّمَ فِيهِ شَيْئًا وَأَخَّرَ وَزَادَ وَنَقَصَ ‏', 'صحيح مسلم — Open-Hadith-Data', true) on conflict (book_id, hadith_number) do update set text_ar=excluded.text_ar, ref=excluded.ref, published=true;
